INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('c754d0fd-55ce-4180-affd-923e84a8d316', '11111111-1111-4111-8111-111111111111', 'product', '813609fd-11c5-46c3-bc9f-7bd2e19d451a', '8a52a699-f74d-4893-a3f3-32d0336408a2', 'docconverter', 'DocConverter', 'ActivePDF DocConverter is a high-volume document-to-PDF converter that transforms a variety of file types to and from PDF. Contact us for a bespoke quote.', 'DocConverter is a high-performance, enterprise-grade file conversion solution designed to efficiently transform a wide range of document formats into PDF or PDF/A with accuracy and speed. Engineered for large-scale operations, it offers centralised management, comprehensive automation, and developer flexibility making it well-suited for organisations seeking dependable, controlled, and straightforward file conversion processes. With DocConverter, organisations can: Automate conversion workflows using APIs, watched folders, or scheduled tasks. Enforce consistent branding and robust security by embedding watermarks, metadata, and encryption. Handle demanding workloads with multithreaded processing and fault-tolerant architecture. Achieve seamless integration within existing Windows server applications and document management pipelines. Retain full operational control,…', '{}', ARRAY['ActivePDF','Conversion']::text[], 'published', false, 'enquiry', NULL, NULL, '{"icon":"assets/catalog/icons/docconverter_1613392987.png","mainImage":"assets/catalog/icons/docconverter_1613392987.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/activepdf/docconverter"}'::jsonb, '{"metaTitle":"ActivePDF DocConverter | Greatstone International | Software","metaDescription":"ActivePDF DocConverter is a high-volume document-to-PDF converter that transforms a variety of file types to and from PDF. Contact us for a bespoke quote.","socialImage":""}'::jsonb, now());
