INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('da80d077-5938-43b4-9d15-0e1663092888', '11111111-1111-4111-8111-111111111111', 'product', '813609fd-11c5-46c3-bc9f-7bd2e19d451a', 'd9850036-dcac-428f-9521-78346e13d26c', 'meridian', 'Meridian', 'Meridian is a networked virtual PDF printer engineered for server-side rendering, enabling developers to empower users to leverage enterprise computing power.', 'ActivePDF Meridian Networked Virtual PDF Printing for Enterprise ActivePDF Meridian is a scalable, server-based virtual PDF printer designed to streamline and centralise PDF generation across your organisation. With Meridian, end users can simply print from any Windows application, and their output is converted into high-quality PDFs automatically eliminating the need for manual conversions or complex client software. Meridian supports networked deployment, round-trip printing, and server-side rendering, making PDF generation seamless and transparent to users while being fully controllable by IT and development teams. Key Features & Capabilities Virtual Network PDF Printer Deploy a centrally managed printer that all clients can use without installing local software. Server-Based Installation, Client Print Drivers Users print as usual; the PDF conversion is handled on…', '{}', ARRAY['ActivePDF','PDF']::text[], 'published', false, 'enquiry', NULL, NULL, '{"icon":"assets/catalog/icons/meridian_1613393034.png","mainImage":"assets/catalog/icons/meridian_1613393034.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/activepdf/meridian"}'::jsonb, '{"metaTitle":"ActivePDF Meridian | Greatstone International | Software","metaDescription":"Meridian is a networked virtual PDF printer engineered for server-side rendering, enabling developers to empower users to leverage enterprise computing power.","socialImage":""}'::jsonb, now());
