INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('0f5b3ae7-1ddf-40de-bced-612a078544bf', '11111111-1111-4111-8111-111111111111', 'product', '813609fd-11c5-46c3-bc9f-7bd2e19d451a', 'd9850036-dcac-428f-9521-78346e13d26c', 'server', 'Server', 'ActivePDF Server is a Print-To-PDF solution that developers can use to empower end-user applications with seamless PDF printing capability.', 'ActivePDF Server Enterprise-Grade, High-Volume PDF Generation & Automation ActivePDF Server is an advanced server-side PDF SDK designed for demanding, high-volume production environments. It enables seamless conversion of print streams, PostScript, PCL, XPS, or image formats into comprehensive PDFs programmatically. With extensive control over output specifications, security protocols, and integration options, ActivePDF Server supports the automation of document pipelines, backend infrastructure, and enterprise-level workflows. Key Features & Capabilities Print-to-PDF Integration Effortlessly convert any printable output from Windows-based applications to PDF files. Multi-format Conversion Supports input from PostScript, PCL, XPS, and various image formats for conversion to PDF. Standards Compliance Generates ISO-compliant outputs such as PDF/A and PDF/X to meet…', '{}', ARRAY['ActivePDF','PDF']::text[], 'published', false, 'enquiry', NULL, NULL, '{"icon":"assets/catalog/icons/server_1613393093.png","mainImage":"assets/catalog/icons/server_1613393093.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/activepdf/server"}'::jsonb, '{"metaTitle":"ActivePDF Server | Greatstone International | Software","metaDescription":"ActivePDF Server is a Print-To-PDF solution that developers can use to empower end-user applications with seamless PDF printing capability.","socialImage":""}'::jsonb, now());
