INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('e6769f72-113b-42ca-80ef-bf42169cffb8', '11111111-1111-4111-8111-111111111111', 'product', '813609fd-11c5-46c3-bc9f-7bd2e19d451a', 'd9850036-dcac-428f-9521-78346e13d26c', 'toolkit', 'Toolkit', 'ActivePDF Toolkit Ultimate is a powerful PDF software development kit that developers can use to Convert, Create, Render, Redact and Print PDF documents.', 'ActivePDF Toolkit Complete Control Over PDF Creation & Manipulation ActivePDF Toolkit is a powerful SDK that gives developers everything they need to generate, modify, and secure PDFs programmatically. Whether you need to merge documents, add digital signatures, or extract content, Toolkit offers the flexibility and performance required for enterprise-grade PDF workflows. With support for both .NET and COM, and compatibility across 32-bit and 64-bit systems, Toolkit integrates seamlessly into your existing applications, giving you fine-grained control over every aspect of your PDF output. Key Features & Capabilities PDF Creation & Assembly Build PDFs from scratch or merge multiple files into a single, unified document. Content Manipulation Insert, update, or extract text, images, metadata, and barcodes. Security & Compliance Apply encryption, digital signatures,…', '{}', ARRAY['ActivePDF','PDF']::text[], 'published', true, 'enquiry', NULL, NULL, '{"icon":"assets/catalog/icons/toolkit-ultimate_1613393148.png","mainImage":"assets/catalog/icons/toolkit-ultimate_1613393148.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/activepdf/toolkit"}'::jsonb, '{"metaTitle":"ActivePDF Toolkit Ultimate | Greatstone International","metaDescription":"ActivePDF Toolkit Ultimate is a powerful PDF software development kit that developers can use to Convert, Create, Render, Redact and Print PDF documents.","socialImage":""}'::jsonb, now());
