INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('cf3aefb0-99cd-46b9-8b3b-3997b20954ee', '11111111-1111-4111-8111-111111111111', 'product', '813609fd-11c5-46c3-bc9f-7bd2e19d451a', '8a52a699-f74d-4893-a3f3-32d0336408a2', 'webgrabber', 'WebGrabber', 'ActivePDF WebGrabber is an HTML-to-PDF server application, rendering W3C HTML5, CSS2/3, JavaScript, Flash, and form ﬁelds to PDF.', 'ActivePDF WebGrabber HTML / Web-to-PDF Rendering Engine ActivePDF WebGrabber is a server-side HTML-to-PDF SDK designed for enterprise use. It processes content from web pages, URLs, or HTML sources and converts them into PDF files that comply with relevant standards. The product supports both .NET and COM APIs, offers configurable rendering engines, and provides options to customise output. WebGrabber can be used to automate document workflows, facilitate archiving, generate reports, or integrate PDF conversion within existing pipelines. Key Features & Capabilities HTML-to-PDF Conversion Converts HTML from URLs, local files, or streams into PDFs. Dual Rendering Engines Offers Native and IE rendering options for different needs. .NET & COM APIs Provides multiple integration methods. Standards & Compliance Produces PDF/A or PDF/X formatted documents. Multi-threading &…', '{}', ARRAY['ActivePDF','Conversion']::text[], 'published', false, 'enquiry', NULL, NULL, '{"icon":"assets/catalog/icons/webgrabber_1613393206.png","mainImage":"assets/catalog/icons/webgrabber_1613393206.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/activepdf/webgrabber"}'::jsonb, '{"metaTitle":"ActivePDF WebGrabber | Greatstone International | Software","metaDescription":"ActivePDF WebGrabber is an HTML-to-PDF server application, rendering W3C HTML5, CSS2/3, JavaScript, Flash, and form ﬁelds to PDF.","socialImage":""}'::jsonb, now());
