INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('02de15d5-bd19-421b-9643-d73769e52f94', '11111111-1111-4111-8111-111111111111', 'product', '3091808f-8fdb-4408-ac8b-6b30820eebb9', 'd9850036-dcac-428f-9521-78346e13d26c', 'apryse-for-appian', 'Apryse for Appian Platform', 'Streamline workflows and allow users to review, approve, digitally sign, and comment on any document with Apyrse for Appian. Explore now with Greatstone.', 'Effortlessly collaborate on PDF, DOCX, XLSX, PPTX and image files with ease. Search, highlight, and annotate your documents with rich mark-ups. Easily edit PDF text, apply styling, and manipulate images directly within Appian, and save your work to Appian without any hassle. Create and edit DOCX files directly in Appian, and customize the styling, fonts, font sizes, and organize your documents . Create custom signing workflows for optimized signing. Place signature fields, assign signers, collect and certify digital signatures. Insert, remove, rearrange pages, merge, split, and assemble documents with a few clicks. Compare multiple documents like a pro. Efficiently remove all sensitive information from documents while ensuring that they remain fully searchable.', ARRAY['Appian']::text[], ARRAY['Apryse','PDF','Appian']::text[], 'published', false, 'enquiry', NULL, NULL, '{"icon":"assets/catalog/icons/appianicon_1714740196.png","mainImage":"assets/catalog/icons/appianicon_1714740196.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/apryse/apryse-for-appian"}'::jsonb, '{"metaTitle":"Apryse for Appian | Products | Greatstone International","metaDescription":"Streamline workflows and allow users to review, approve, digitally sign, and comment on any document with Apyrse for Appian. Explore now with Greatstone.","socialImage":""}'::jsonb, now());
