INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('da4580cc-d9eb-45b5-92fa-5479d923fc44', '11111111-1111-4111-8111-111111111111', 'product', '3091808f-8fdb-4408-ac8b-6b30820eebb9', 'd9850036-dcac-428f-9521-78346e13d26c', 'apryse-for-mendix', 'Apryse for Mendix Platform', 'Enhance your app with seamless document management with Apryse for Mendix. Request a call to revolutionise your document workflows with Greatstone.', 'Collaborate and mark-up PDF, DOCX, XLSX, PPTX, and image files with ease. Edit PDF text, apply styling, and manipulate images directly in the Mendix instance. Create, pre-fill, sign, extract, and flatten PDF forms with data stored in Mendix. Create, style, organize DOCX natively in Mendix, with WYSIWYG in word processors. Compare, assemble, merge, split documents in your browser in the same viewer. Create documents from any data source to populate templates in PDF, DOCX, HTML .', ARRAY['Mendix']::text[], ARRAY['Apryse','PDF','Mendix']::text[], 'published', false, 'enquiry', NULL, NULL, '{"icon":"assets/catalog/icons/mendixicon_1714743127.png","mainImage":"assets/catalog/icons/mendixicon_1714743127.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/apryse/apryse-for-mendix"}'::jsonb, '{"metaTitle":"Apryse for Mendix | Products | Greatstone International","metaDescription":"Enhance your app with seamless document management with Apryse for Mendix. Request a call to revolutionise your document workflows with Greatstone.","socialImage":""}'::jsonb, now());
INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('11528200-c173-414f-88c1-5a1dc124192b', '11111111-1111-4111-8111-111111111111', 'product', '3091808f-8fdb-4408-ac8b-6b30820eebb9', 'd9850036-dcac-428f-9521-78346e13d26c', 'apryse-for-outsystems', 'Apryse for OutSystems', 'Apryse for OutSystems', 'Collaborate on and annotate PDFs, DOCX, XLSX, PPTX, and images with search and highlighting capabilities. Edit PDF text, apply styling, and manipulate images directly in OutSystems and save to the OutSystems database Support form filling, FDF, and JavaScript. Create, pre-fill, sign, extract, and flatten PDF forms with data from storage providers Edit DOCX files natively in OutSystems with true WYSIWYG output quality. Apply styling, adjust fonts, and organize with lists. Manage documents in your browser. Insert, remove, rearrange pages. Merge, split documents. Compare documents side-by-side. Create customized documents by filling in templates with data from any source, either within or outside the OutSystems platform.', ARRAY['OutSystems']::text[], ARRAY['Apryse','PDF','OutSystems']::text[], 'published', false, 'enquiry', NULL, NULL, '{"icon":"assets/catalog/icons/outsystems_1714749225.png","mainImage":"assets/catalog/icons/outsystems_1714749225.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/apryse/apryse-for-outsystems"}'::jsonb, '{"metaTitle":"Apryse for OutSystems | Greatstone","metaDescription":"Apryse for OutSystems","socialImage":""}'::jsonb, now());
INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('67d990de-b261-4de7-90f8-e9813c0d7c60', '11111111-1111-4111-8111-111111111111', 'product', '3091808f-8fdb-4408-ac8b-6b30820eebb9', 'd9850036-dcac-428f-9521-78346e13d26c', 'apryse-for-salesforce', 'Apryse for Salesforce', 'Unlock the potential of Salesforce with Apryse, the comprehensive document generation and collaboration solution. Request a call from Greatstone International.', 'Enable searchable and editable viewing for PDF, DOCX, PPTX files instead of static previews. Collaborate better with document markup, rapid estimation, and saved annotations in Salesforce. Prepopulate data into forms on Salesforce or any other storage providers like AWS, Azure, GCP, IBM Cloud and more. Customise signing workflows, place signature fields, assign signers, collect, certify and validate signatures. Assemble, merge, remove, or rearrange pages and view multiple documents ,split documents directly in the browser. Remove sensitive information from documents while keeping them searchable, including personal and protected health information.', ARRAY['Salesforce']::text[], ARRAY['Apryse','PDF','Salesforce']::text[], 'published', false, 'enquiry', NULL, NULL, '{"icon":"assets/catalog/icons/salesforceicon_1714735881.png","mainImage":"assets/catalog/icons/salesforceicon_1714735881.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/apryse/apryse-for-salesforce"}'::jsonb, '{"metaTitle":"Apryse for Salesforce | Products | Greatstone International","metaDescription":"Unlock the potential of Salesforce with Apryse, the comprehensive document generation and collaboration solution. Request a call from Greatstone International.","socialImage":""}'::jsonb, now());
