INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('75f16ac1-5d8f-49f4-bbc2-f166d23ca592', '11111111-1111-4111-8111-111111111111', 'product', '3091808f-8fdb-4408-ac8b-6b30820eebb9', 'd9850036-dcac-428f-9521-78346e13d26c', 'apryse-for-sharepoint', 'Apryse for SharePoint', 'Apryse for SharePoint', 'Collaborate on and annotate PDFs, CAD files, images, videos, and websites with search and highlighting functions. Effortlessly edit and style PDF text and images directly in your SharePoint instance, and securely save to your SharePoint database. Enable interactive form filling, FDF, and embedded JavaScript. Create, pre-fill, sign, extract, and flatten PDF forms . Create documents by filling in PDF, DOCX, or HTML templates with data from any data source, inside or outside SharePoint. Reorder, add, remove pages, merge, split documents in your browser. Compare multiple documents side-by-side in a single viewer. Search for and remove sensitive information such as personally identifiable information (PII) or other confidential data, while keeping documents searchable.', ARRAY['SharePoint']::text[], ARRAY['Apryse','PDF','SharePoint']::text[], 'published', false, 'enquiry', NULL, NULL, '{"icon":"assets/catalog/icons/sharepointicon_1714752206.png","mainImage":"assets/catalog/icons/sharepointicon_1714752206.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/apryse/apryse-for-sharepoint"}'::jsonb, '{"metaTitle":"Apryse for SharePoint | Greatstone","metaDescription":"Apryse for SharePoint","socialImage":""}'::jsonb, now());
