INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('a2aaf9a8-f4ea-4804-97e1-311be17ebc28', '11111111-1111-4111-8111-111111111111', 'product', '3091808f-8fdb-4408-ac8b-6b30820eebb9', 'd9850036-dcac-428f-9521-78346e13d26c', 'apryse-web-sdk', 'Apryse Web SDK', 'All-in-one document powerhouse with Apryse WebViewer. Render, convert & edit PDFs, Office docs, images & more. Available with Greatstone International.', 'Automate data entry, fill, edit, or create new forms with ease. Compare PDFs with overlays & highlighted differences. Measure quickly and accurately with snap-to geometry. Native DOCX editing, producing true WYSIWYG output quality. Choose 35+ annotations for real-time collaboration. Create custom signing workflows with validation. Redact specific areas or entire pages, including images and text. Merge Office templates with JSON data on the client-side.', '{}', ARRAY['Apryse','PDF']::text[], 'published', false, 'enquiry', NULL, NULL, '{"icon":"assets/catalog/icons/wewb-icon_1714573583.png","mainImage":"assets/catalog/icons/wewb-icon_1714573583.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/apryse/apryse-web-sdk"}'::jsonb, '{"metaTitle":"Apryse Web SDK | Products | Greatstone International","metaDescription":"All-in-one document powerhouse with Apryse WebViewer. Render, convert & edit PDFs, Office docs, images & more. Available with Greatstone International.","socialImage":""}'::jsonb, now());
