INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('e4ac6db0-0d6b-41a5-8475-61ed3cf49cce', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '8fdaf92d-fda0-4c2b-b2ba-e75b8e9c8abc', 'aspose-tex-for-c++', 'Aspose TeX for C++', 'Aspose TeX for C++', 'Aspose.TeX for Java is a versatile typeset TeX file library. This new API from the file format giants, Aspose, supports several output formats, including JPEG, TIFF, BMP, XPS, PDF and PNG. It is also able to create bespoke TeX format for developers looking to create or typeset uniformly designed documents Aspose.Tex Input Formats Plain text TeX files Aspose.Tex Output Formats JPEG TIFF BMP XPS PDF PNG', ARRAY['C++']::text[], ARRAY['Aspose','Typesetting','C++']::text[], 'published', false, 'license', 29000, 'GBP', '{"icon":"assets/catalog/icons/aspose_tex-for-cpp.png","mainImage":"assets/catalog/icons/aspose_tex-for-cpp.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-tex-for-c++"}'::jsonb, '{"metaTitle":"Aspose TeX for C++ | Greatstone","metaDescription":"Aspose TeX for C++","socialImage":""}'::jsonb, now());
