INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('f9e32661-6a94-4d24-9a08-3fefc5e926cd', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '42323758-6c49-488f-80bf-86caec7c6d8c', 'aspose-barcode-for--net', 'Aspose.BarCode for .NET', 'Aspose.BarCode for .NET API allows developers to add Barcode recognition, scanning, and generation functionality to their .NET applications.', 'Aspose.BarCode for .NET is a comprehensive developer library used to recognize & generate 2D & 1D barcodes from many image types at any viewpoint. Developers are able to add the barcode scanning and generation features in their .NET applications and also allow export generated barcodes to different high-fidelity image formats. Developers can also manipulate the appearance and features of barcodes generated like bar color, background color, rotation angle, resolution, x-dimension, image quality, captions, size, and a lot more. The API supports a variety of imaging and recognition and various types of symbologies. Aspose.Barcode Input/Output Formats JPEG TIFF PNG BMP GIF EXIF Aspose.Barcode Output Formats EMF SVG Aspose.Barcode Supported Barcode Symbols The Aspose.Barcode library supports multiple 2D, 1D, and postal bar code symbologies for encoding and decoding…', ARRAY['.NET']::text[], ARRAY['Aspose','Barcode & QR','.NET']::text[], 'published', false, 'license', 72500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.BarCode-for-.NET.png","mainImage":"assets/catalog/icons/Aspose.BarCode-for-.NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-barcode-for--net"}'::jsonb, '{"metaTitle":"Aspose.BarCode for .NET | Greatstone Software","metaDescription":"Aspose.BarCode for .NET API allows developers to add Barcode recognition, scanning, and generation functionality to their .NET applications.","socialImage":""}'::jsonb, now());
