INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('f8c0d3db-4ca0-472e-af94-b998cf5deb75', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '030cde89-bd55-4d78-a3f2-3acaf1e59391', 'aspose-barcode-for-jasperreports', 'Aspose.BarCode for JasperReports', 'Aspose.BarCode for JasperReports', 'Aspose.BarCode for JasperReports is a versatile JasperServer and JasperReports extension to build, display and create barcode labels in your applications. These barcode labels can be rendered in multiple popular image formats. Aspose.BarCode for JasperReports Output Formats: Images: JPEG, PNG, BMP, GIF, TIFF, EXIF Others: EMF, SVG Complete Package for 1D, 2D & Postal Barcodes Aspose.BarCode for JasperReports supports over 40 of the most popular 1D, 2D and postal barcode symbologies including: Datamatrix EAN 8 EAN 13 EAN 14 (SCC14) EAN 128 Identcode Interleaved 2 of 5 Itf14 Leticode MacroPdf417 Matrix 2 of 5 Australia Post Aztec BooklandEAN (ISBN) Codabar Code39 Code93 Code11 Code128 MSI OneCode OPC Pdf417 Planet Postnet QR SSCC 18 Standard 2 of 5 Supplement Code +2 (For EAN and UPC code) Supplement Code +5 (For EAN and UPC code) UPC A UPC E VIN Barcode Images…', ARRAY['JasperReports']::text[], ARRAY['Aspose','Document Automation','JasperReports']::text[], 'published', false, 'license', 72500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.BarCode-for-JasperReports.png","mainImage":"assets/catalog/icons/Aspose.BarCode-for-JasperReports.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-barcode-for-jasperreports"}'::jsonb, '{"metaTitle":"Aspose.BarCode for JasperReports | Greatstone","metaDescription":"Aspose.BarCode for JasperReports","socialImage":""}'::jsonb, now());
