INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('a8e039c9-33eb-4212-adde-bf318bdba12e', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '42323758-6c49-488f-80bf-86caec7c6d8c', 'aspose-barcode-for-java', 'Aspose.BarCode for Java', 'Aspose.BarCode for Java', 'Aspose.BarCode for Java is a comprehensive developer library used to recognize & generate 2D & 1D barcodes from many image types at any viewpoint. Developers are able to add the barcode scanning and generation features in their Java applications and also allow export generated barcodes to different high-fidelity image formats. Developers can also manipulate the appearance and features of barcodes generated like bar color, background color, rotation angle, resolution, x-dimension, image quality, captions, size, and a lot more. The API supports a variety of imaging and recognition and various types of symbologies. Aspose.BarCode Input/Output Formats JPEG TIFF PNG BMP GIF EXIF Aspose.BarCode Output Formats EMF SVG Aspose.Barcode Supported Barcode Symbols The Aspose.Barcode library supports multiple 2D, 1D, and postal bar code symbologies for encoding and decoding…', ARRAY['Java']::text[], ARRAY['Aspose','Barcode & QR','Java']::text[], 'published', false, 'license', 72500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.BarCode-for-Java.png","mainImage":"assets/catalog/icons/Aspose.BarCode-for-Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-barcode-for-java"}'::jsonb, '{"metaTitle":"Aspose.BarCode for Java | Greatstone","metaDescription":"Aspose.BarCode for Java","socialImage":""}'::jsonb, now());
