INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('40e9b391-ded0-42e4-bec7-1b1c82c6a3ae', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '42323758-6c49-488f-80bf-86caec7c6d8c', 'aspose-barcode-for-sharepoint', 'Aspose.BarCode for SharePoint', 'Aspose.BarCode for SharePoint', 'Aspose.BarCode for SharePoint is a SharePoint developer API for adding multiple of 1D, 2D and postal barcode symbologies to Microsoft Office SharePoint Server 2010 (MOSS) and MSSharePoint Foundation 2010 lists. Developers are also able to add barcodes to lists by giving the code text and symbology. Aspose.BarCode for SharePoint Input and Output Formats BMP GIF JPEG TIFF PNG EXIF Aspose.BarCode for SharePoint Output Formats SVG EMF Add Barcode Columns to SharePoint Lists Developers can use the Aspose.BarCode for SharePoint library to add a barcode type column to SharePoint lists with only a couple of lines of code. They can also set the barcode code text using the Graphical User Interface or by integrating the Service Markers module. Supported Barcode Symbologies: SharePoint barcode app supports all leading symbologies, including: EAN13 EAN14 EAN8 GS1DataMatrix…', ARRAY['SharePoint']::text[], ARRAY['Aspose','Barcode & QR','SharePoint']::text[], 'published', false, 'license', 72500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.BarCode-for-SharePoint.png","mainImage":"assets/catalog/icons/Aspose.BarCode-for-SharePoint.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-barcode-for-sharepoint"}'::jsonb, '{"metaTitle":"Aspose.BarCode for SharePoint | Greatstone","metaDescription":"Aspose.BarCode for SharePoint","socialImage":""}'::jsonb, now());
