INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('98042b35-bd28-4d5f-b3b5-0568f0dc2d57', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'ecdf7e8e-bdf3-4009-97f6-e391275375fe', 'aspose-cad-for-java', 'Aspose.CAD for Java', 'Aspose.CAD for Java', 'Aspose.CAD for Java is a unique AutoCAD processing and automation library. It gives developers the ability to convert DWF, DWG, and DXF files format to high-fidelity raster and PDF images. They can convert and select specific layers and layouts from AutoCAD files and monitor the entire file conversion process. Aspose.CAD Input Formats DWG 2000/2000i/2002 DWG 2004/2005/2006 Autodesk DWF DGN Industry Foundation Classes (IFC) DWG 2010/2011/2012 DWG Release 11, 12, 13, 14 DWG 2013/2014/2015/2016 AutoCAD DXF STereoLithography (STL) Aspose.CAD Output Formats Raster Images: PNG, BMP, TIFF, JPEG, GIF Fixed Layout: PDF CAD Conversion to PDF The Aspose.CAD for Java API gives developers the capability to dynamically convert supported Computer Aided Drawings(CAD) to the industry-standard PDF format for further processing. Developers can customise the conversion process to…', ARRAY['Java']::text[], ARRAY['Aspose','Imaging & Graphics','Java']::text[], 'published', false, 'license', 58000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.CAD-for-Java.png","mainImage":"assets/catalog/icons/Aspose.CAD-for-Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-cad-for-java"}'::jsonb, '{"metaTitle":"Aspose.CAD for Java | Greatstone","metaDescription":"Aspose.CAD for Java","socialImage":""}'::jsonb, now());
