INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('cb7afafd-d635-4fc0-92c8-89a40901fe3c', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'dc8fc4d3-68b8-4b41-97d9-76bcf1dd75af', 'aspose-cells-for--net', 'Aspose.Cells for .NET', 'Aspose.Cells for .NET is a Spreadsheet Programming API that helps developers automate spreadsheet processing and management tasks.', 'Aspose.Cells for .NET is a Spreadsheet Programming API that helps developers automate spreadsheet processing and management tasks. Developers can build cross-platform applications with the functionality to Render, Generate, Modify, Convert, and Print spreadsheets. The key USP of Aspose.Cells for .NET is it does not require Microsoft s spreadsheet management component MS Excel or MS Office Interop components. Managing multiple worksheets, adding common and complex Mathematical, Financial, and Text formulas, manipulating charts, creating spreadsheet styles and content from scratch, importing data onto the worksheets from different data sources, drawing objects, pictures, and comments can be achieved via the Aspose.Cells API. Aspose.Cells Input and Output Fomats Microsoft Excel: XLS, XLTX, XLTM, , XLSX, XLSB, XLT , XML, XLSM Text: CSV, TSV OpenOffice: ODS Numbers: Apple…', ARRAY['.NET']::text[], ARRAY['Aspose','Spreadsheets','.NET']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Cells-for-.NET.png","mainImage":"assets/catalog/icons/Aspose.Cells-for-.NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-cells-for--net"}'::jsonb, '{"metaTitle":"Aspose.Cells for .NET | Aspose | Greatstone International","metaDescription":"Aspose.Cells for .NET is a Spreadsheet Programming API that helps developers automate spreadsheet processing and management tasks.","socialImage":""}'::jsonb, now());
