INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('537cece1-f1f9-423f-acf0-f8eec9a3409e', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'dc8fc4d3-68b8-4b41-97d9-76bcf1dd75af', 'aspose-cells-for-android-via-java', 'Aspose.Cells for Android via Java', 'Aspose.Cells for Android via Java', 'The Aspose.Cells for Android via Java library is a versatile developer solution to combine, modify, parse and generate spreadsheets files programmatically. The library provides a vast array of features functions and methods including rendering Excell worksheet pages to raster images and specifying image resolution, quality and compression, adding charts, document formatting, page setup, import and export capabilities and more. Formats supported by the API include ODS, Tab Delimited, HTML, XLS, XLSX, CSV, SpreadsheetML, PDF, XPS, and more. Aspose.Cells for Android via Java Input and Output format: Microsoft Excel: XLTM, XLSM, XML, XLS, XLSX, XLSB, XLTX, OpenOffice: ODS Text: CSV, TXT, TSV Web: HTML, MHTML Aspose.Cells for Android via Java Output format: Fixed Layout: PDF, PDF/A, XPS Images: JPEG, PNG, BMP, SVG, EMF Conversion to and from different formats The…', ARRAY['Java','Android']::text[], ARRAY['Aspose','Spreadsheets','Java','Android']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Cells-for-Android-via-Java.png","mainImage":"assets/catalog/icons/Aspose.Cells-for-Android-via-Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-cells-for-android-via-java"}'::jsonb, '{"metaTitle":"Aspose.Cells for Android via Java | Greatstone","metaDescription":"Aspose.Cells for Android via Java","socialImage":""}'::jsonb, now());
