INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('8fb513e5-df41-43c8-8f69-049efbe2e0db', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'dc8fc4d3-68b8-4b41-97d9-76bcf1dd75af', 'aspose-cells-for-java', 'Aspose.Cells for Java', 'Aspose.Cells for Java is a Spreadsheet Programming API that helps developers automate spreadsheet processing and management tasks.', 'Aspose.Cells for Java is a Spreadsheet Programming API that helps developers automate spreadsheet processing and management tasks. Developers can build cross-platform applications with the functionality to Render, Generate, Modify, Convert, and Print spreadsheets. The key USP of Aspose.Cells for Java is it does not require Microsoft s spreadsheet management component MS Excel or MS Office Interop components. Managing multiple worksheets, adding common and complex Mathematical, Financial, and Text formulas, manipulating charts, creating spreadsheet styles and content from scratch, importing data onto the worksheets from different data sources, drawing objects, pictures, and comments can be achieved via the Aspose.Cells API. Aspose.Cells Input and Output Formats Microsoft Excel: XLS, XLTX, XLTM, , XLSX, XLSB, XLT , XML, XLSM Text: CSV, TSV OpenOffice: ODS Numbers:…', ARRAY['Java']::text[], ARRAY['Aspose','Spreadsheets','Java']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Cells-for-Java.png","mainImage":"assets/catalog/icons/Aspose.Cells-for-Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-cells-for-java"}'::jsonb, '{"metaTitle":"Aspose.Cells for Java | Aspose | Greatstone International","metaDescription":"Aspose.Cells for Java is a Spreadsheet Programming API that helps developers automate spreadsheet processing and management tasks.","socialImage":""}'::jsonb, now());
