INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('9aeeeba7-c7c9-4151-a61f-4d28b7aff955', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '030cde89-bd55-4d78-a3f2-3acaf1e59391', 'aspose-cells-for-reporting-services', 'Aspose.Cells for Reporting Services', 'Aspose.Cells for Reporting Services allows developers to export Excel reports from Microsoft Report Viewer and Microsoft SQL Server Reporting Services.', 'Aspose.Cells for Reporting Services allows developers to export Excel reports from Microsoft Report Viewer and Microsoft SQL Server Reporting Services. Aspose.Cells for Reporting Services permits the conversion of RDLC & RDL reports to multiple Excel spreadsheet file formats; unlike the native exporter for Excel-based reports. Aspose.Cells for Reporting Services Input Formats RDL RDLC Aspose.Cells for Reporting Services Output Formats Microsoft Excel: XLS, XLSX, XLSM, XLSB, XML OpenOffice: ODS Web: HTML Text: CSV, TSV, TabDelimited text file Fixed Layout: XPS Reports Designer Tool Developers can use Aspose.Cells.Report.Designer to build, deliver and design reports natively from Microsoft Excel while using an intuitive designing tool based on Microsoft Excel as its report template. This unique feature utilises the powerful functionality available in Microsoft s Excel…', ARRAY['Reporting Services']::text[], ARRAY['Aspose','Document Automation','Reporting Services']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Cells-for-Reporting-Services.png","mainImage":"assets/catalog/icons/Aspose.Cells-for-Reporting-Services.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-cells-for-reporting-services"}'::jsonb, '{"metaTitle":"Aspose.Cells for Reporting Services | Greatstone",