INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('ca7231c5-ed31-4274-8c66-10c85a043f1b', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'c596882e-12e5-4978-89d1-3ee35d7eb2ff', 'aspose-diagram-for--net', 'Aspose.Diagram for .NET', 'Aspose.Diagram for .NET', 'Aspose.Diagram for .NET is an API built from the ground up to work with Microsoft s popular Visio document format. It gives developers the ability to manipulate, convert, and create native VSDX file formats. They can build diagrams from scratch and also load existing Visio files to manipulate the elements of the diagram for export to other formats for further processing. Aspose.Diagram for .NET supports all native Visio formats plus commonly used fixed-layout and image formats. The API is an alternative to Microsoft s Visio Object Model and provides superior performance. It utilises the advanced functionality of Visio Services to automate server-based documents. Aspose.Diagram Input/Output Formats Microsoft Visio: VSDX, VSTX, VSDM, VSSM, VSTM VSX, VTX, VDX, VSSX, Aspose.Diagram Input Formats Microsoft Visio: VSS, VST, VDW, VSD, Aspose.Diagram Output Formats Fixed…', ARRAY['.NET']::text[], ARRAY['Aspose','Diagrams','.NET']::text[], 'published', false, 'license', 58000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Diagram-for-.NET.png","mainImage":"assets/catalog/icons/Aspose.Diagram-for-.NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-diagram-for--net"}'::jsonb, '{"metaTitle":"Aspose.Diagram for .NET | Greatstone","metaDescription":"Aspose.Diagram for .NET","socialImage":""}'::jsonb, now());
