INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('0940dd80-56c5-4199-aac5-bcfe89d30f9b', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'c596882e-12e5-4978-89d1-3ee35d7eb2ff', 'aspose-diagram-for-java', 'Aspose.Diagram for Java', 'Aspose.Diagram for Java', 'Aspose.Diagram for Java is an API built from the ground up to work with Microsoft s popular Visio document format. It gives developers the ability to manipulate, convert and create native VSDX file formats. They can build diagrams from scratch and also load existing Visio files to manipulate the elements of the diagram for export to other formats for further processing. Aspose.Diagram for Java supports all native Visio formats plus commonly used fixed-layout and image formats. The API is an alternative to Microsoft s Visio Object Model and provides superior performance. It utilises the advanced functionality of Visio Services to automate server-based documents. Aspose.Diagram Input/Output Formats Microsoft Visio: VSDX, VSTX, VSDM, VSSM, VSTM VSX, VTX, VDX, VSSX, Aspose.Diagram Input Only Formats Microsoft Visio: VSS, VST, VDW, VSD, Aspose.Diagram Output Only Formats…', ARRAY['Java']::text[], ARRAY['Aspose','Diagrams','Java']::text[], 'published', false, 'license', 58000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Diagram-for-Java.png","mainImage":"assets/catalog/icons/Aspose.Diagram-for-Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-diagram-for-java"}'::jsonb, '{"metaTitle":"Aspose.Diagram for Java | Greatstone","metaDescription":"Aspose.Diagram for Java","socialImage":""}'::jsonb, now());
