INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('81109d07-045b-401e-a7e1-8f57306d875e', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '073f97d7-4b12-493a-9733-7fd47dad38a3', 'aspose-email-for--net', 'Aspose.Email for .NET', 'Aspose.Email for .NET', 'Aspose.Email for .NET is an Email automation API that is used to develop multi-platform applications with the ability to build, analyse, manipulate, transmit, and convert email messages without Microsoft Outlook or Office Automation. The API provides manipulation features, including extraction, addition, and removal of email attachments, customisation of email headers by amending recipients, email subject, and loads more. Aspose.Email for .NET supports Microsoft Outlook & Mozilla Thunderbird email client formats including EML, MSG, EMLX, OST, PST, MBOX, and MHT and provides the functionality to manipulate email archive files like PST, OST, and MBOX. Developers can automate email transmission via industry-standard protocols like IMAP, POP3 & SMTP, Exchange Web Services to receive & send emails with attachments and delete or list messages from the server & Microsoft…', ARRAY['.NET']::text[], ARRAY['Aspose','Email','.NET']::text[], 'published', false, 'license', 72500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Email-for-.NET.png","mainImage":"assets/catalog/icons/Aspose.Email-for-.NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-email-for--net"}'::jsonb, '{"metaTitle":"Aspose.Email for .NET | Greatstone","metaDescription":"Aspose.Email for .NET","socialImage":""}'::jsonb, now());
