INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('3919e33a-4700-4079-a899-9e28c974c3fa', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '073f97d7-4b12-493a-9733-7fd47dad38a3', 'aspose-email-product-family', 'Aspose.Email Product Family', 'Create, Manipulate and Convert Outlook email & storage files and implement network protocols such as SMTP, POP3 & IMAP with the Aspose.Email product family.', '.NET, Java, Android, C++, Android, SharePoint, and Python API s and Libraries to Create, Manipulate and Convert Outlook email & storage files. Implement network protocols such as SMTP, POP3 & IMAP. Aspose.Email Product Suite Includes: Aspose.Email for .NET Automate PST, EML, MSG, MHT in ASP.NET, Web Services Aspose.Email for Java Build, Manipulate, Transmit, Convert email messages in Java Aspose.Email for C++ Edit, Create, Convert email message archives & files in C++ Aspose.Email for Android via Java Manipulate, Create, Convert emails & archive files in Android Aspose.Email for SharePoint Convert, Synchronise Email file formats in SharePoint Aspose.Email for Python via .NET Python library to create, manipulate, convert, send or receive email messages.', '{}', ARRAY['Aspose','Email']::text[], 'published', false, 'license', 101500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Email-Product-Family.png","mainImage":"assets/catalog/icons/Aspose.Email-Product-Family.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-email-product-family"}'::jsonb, '{"metaTitle":"Aspose.Email Product Family | Greatstone International","metaDescription":"Create, Manipulate and Convert Outlook email & storage files and implement network protocols such as SMTP, POP3 & IMAP with the Aspose.Email product family.","socialImage":""}'::jsonb, now());
