INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('b49ead5a-e558-4a93-b3d3-83b132879d4a', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'ecdf7e8e-bdf3-4009-97f6-e391275375fe', 'aspose-gis-for--net', 'Aspose.GIS for .NET', 'Aspose.GIS for .NET', 'Aspose.GIS for .NET provides and library for developers to manipulate & access geographic information from vector-based geospatial data formats. The API supports writing, read & convert most of the popular GIS file-formats including FIleGDB, Shapefile, GeoJSON, KML & OSM XML as well the ability to render a map from all supported formats to SVG. Developers can also customise rendering and feature settings and styles to get a bespoke map look and feel. Aspose.GIS for .NET is built from the ground up with usability, portability, simplicity, and performance at its core. The library can be used within the .NET Core & Xamarin platform, .NET Framework enabling developers to easily build multi-platform applications. Vector files in Aspose.GIS Geography Markup Language: GML Google Earth: KML GPS Exchange Format: GPX MapInfo Interchange Format: MIF MapInfo Tab Format: TAB,…', ARRAY['.NET']::text[], ARRAY['Aspose','Imaging & Graphics','.NET']::text[], 'published', false, 'license', 58000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.GIS-for-.NET.png","mainImage":"assets/catalog/icons/Aspose.GIS-for-.NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-gis-for--net"}'::jsonb, '{"metaTitle":"Aspose.GIS for .NET | Greatstone","metaDescription":"Aspose.GIS for .NET","socialImage":""}'::jsonb, now());
