INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('5d1d9744-e494-4c7a-9d5a-b0a2422d2975', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'ecdf7e8e-bdf3-4009-97f6-e391275375fe', 'aspose-imaging-for-sharepoint', 'Aspose.Imaging for SharePoint', 'Aspose.Imaging for SharePoint', 'Aspose.Imaging for SharePoint allows developers to convert images to diverse image formats, including GIF, PNG, JPEG, BMP, TIFF, and PSD from MS SharePoint. They can also edit exported images by programmatically performing operations like image flipping, cropping, resizing and rotating without requiring an image editor. The Aspose.Imaging for SharePoint API also provides image conversion via an Edit Control Block (ECB) Menu with the Convert Image option added to the ECB menu following installation. Aspose.Imaging for SharePoint Input and Output Formats: Raster Formats: JPEG, BMP, TIFF, GIF, PNG Photoshop: PSD Image Format Inter-conversion With the help of a comprehensive group of enhanced algorithms, Aspose.Imaging for SharePoint is an all-in-one solution for automating image conversion. Developers can perform 2-way conversions from a vast number of popular image…', ARRAY['SharePoint']::text[], ARRAY['Aspose','Imaging & Graphics','SharePoint']::text[], 'published', false, 'license', 72500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Imaging-for-SharePoint.png","mainImage":"assets/catalog/icons/Aspose.Imaging-for-SharePoint.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-imaging-for-sharepoint"}'::jsonb, '{"metaTitle":"Aspose.Imaging for SharePoint | Greatstone","metaDescription":"Aspose.Imaging for SharePoint","socialImage":""}'::jsonb, now());
