INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('b5f284a5-3235-47dc-b994-d929c1209ce7', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '2ca61826-821f-4fa6-8db9-ac89b64e7d9d', 'aspose-note-for-java', 'Aspose.Note for Java', 'Aspose.Note for Java', 'Aspose.Note for Java is an individual OneNote document automation API that developers can use to convert, edit, manipulate Microsoft OneNote file formats and the elements of OneNote books; these can then be exported to different popular formats for sharing or further processing. Developers can also navigate through the document object model, extract text from any part of a file, load documents, render text and images from OneNote file to multiple formats, and loads more. Aspose.Note Input/Output Formats Microsoft OneNote: ONE Aspose.Note Input Formats ONETOC2 Aspose.Note Output Formats Fixed Layout: PDF Web: HTML Images: GIF, JPEG, PNG, BMP, TIFF Convert OneNote Files to Diverse Formats Developers can load OneNote files and render them in popular image formats like GIF, TIFF, JPEG, PNG & BMP. The API can also convert OneNote documents to PDF format for further…', ARRAY['Java']::text[], ARRAY['Aspose','Note-taking','Java']::text[], 'published', false, 'license', 58000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Note-for-Java.png","mainImage":"assets/catalog/icons/Aspose.Note-for-Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-note-for-java"}'::jsonb, '{"metaTitle":"Aspose.Note for Java | Greatstone","metaDescription":"Aspose.Note for Java","socialImage":""}'::jsonb, now());
