INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('2dfa19e5-1609-4479-b0bd-39fe9074b5e2', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'd9850036-dcac-428f-9521-78346e13d26c', 'aspose-pdf-for--net', 'Aspose.Pdf for .NET', 'Aspose.Pdf for .NET', 'Aspose.PDF for .NET is a feature-rich developer component that gives developers the ability to Create, Manipulate, Read, Write PDF documents and manage and dynamically fill embedded forms in PDF documents without the need for Adobe Acrobat. Supported Document Formats Aspose.PDF Input Formats XSLFO, MHT, PCL, PS, CGM Aspose.PDF Input/Output Formats Fixed Layout: PDF, PDF/A, PDF/UA, XPS Books: EPUB Web: HTML, MHTML Others: TEX, XML, SVG Aspose.PDF Output Formats Microsoft Office: DOC, DOCX, XLS, XLSX, PPTX Images: JPEG, PNG, BMP, TIFF, EMF Others: MobiXML, XML PDF creation via the Aspose.Pdf for .NET API or XML templates and is straight forward. Fully featured C# and Visual Basic demos and documentation are on hand to quickly get Developers going. Convert Your PDF Documents to PowerPoint, Word, & HTML Developers can implement PDF to Word, PowerPoint, or HTML conversion…', ARRAY['.NET']::text[], ARRAY['Aspose','PDF','.NET']::text[], 'published', true, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.PDF-for-.NET.png","mainImage":"assets/catalog/icons/Aspose.PDF-for-.NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-pdf-for--net"}'::jsonb, '{"metaTitle":"Aspose.Pdf for .NET | Greatstone","metaDescription":"Aspose.Pdf for .NET","socialImage":""}'::jsonb, now());
