INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('2129b2c2-dcaf-455f-8b20-6358fa023f2e', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'd9850036-dcac-428f-9521-78346e13d26c', 'aspose-pdf-for-android-via-java', 'Aspose.Pdf for Android via Java', 'Aspose.Pdf for Android via Java', 'Aspose.PDF for Android Java is a PDF automation developer library that provides Android apps with the feature sets to manipulate, render, read & write PDF documents. A wide range of popular standard file-formats including XPS, Images HTML, TXT & EPUB is fully supported by the API. The Aspose.PDF for Android via Java component is a reasonably priced solution that offers extensive hyperlink functionality, custom font handling, compression options, support for graph objects, extended security controls, bookmark features, integration with data sources, ability to work with attachments, text annotations, annotations and images and a lot more. Aspose.PDF for Android via Java Input and Output formats PDF/A Books: EPUB Web: HTML XML Aspose.PDF for Android via Java Input formats PDF Aspose.PDF for Android via Java Output formats Microsoft Office: DOC, XLS Images: JPEG, PNG,…', ARRAY['Java','Android']::text[], ARRAY['Aspose','PDF','Java','Android']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.PDF-for-Android-via-Java.png","mainImage":"assets/catalog/icons/Aspose.PDF-for-Android-via-Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-pdf-for-android-via-java"}'::jsonb, '{"metaTitle":"Aspose.Pdf for Android via Java | Greatstone","metaDescription":"Aspose.Pdf for Android via Java","socialImage":""}'::jsonb, now());
