INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('47e23b5e-4245-4d77-bc4a-fe83c176c3f7', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'd9850036-dcac-428f-9521-78346e13d26c', 'aspose-pdf-for-c++', 'Aspose.Pdf for C++', 'Aspose.Pdf for C++', 'Aspose.PDF for C++ is a bespoke C++ application development library that developers can use to add PDF automation and processing features to their applications. The API can be used to develop 32-bit and 64-bit C++ applications that can read, generate, manipulate or convert PDF files without requiring Adobe Acrobat. Other document processing features of the API include text & page manipulation, management of annotations, add or remove bookmarks and watermarks, form processing, get and set metadata information, attachments, custom font handling to name a few. Aspose.PDF Input and Output Formats Fixed Layout: PDF, PDF/A Others: TEX, XPS, SVG Aspose.PDF Output Formats Microsoft Word: DOC, DOCX Images: JPEG, PNG, BMP Others: XLSX, PPTX Aspose.PDF In put Formats XSLFO, PS Dynamically Manipulate PDF Files The Aspose.PDF for C++ library is the perfect option for developers…', ARRAY['C++']::text[], ARRAY['Aspose','PDF','C++']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Pdf-for-C__.png","mainImage":"assets/catalog/icons/Aspose.Pdf-for-C__.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-pdf-for-c++"}'::jsonb, '{"metaTitle":"Aspose.Pdf for C++ | Greatstone","metaDescription":"Aspose.Pdf for C++","socialImage":""}'::jsonb, now());
