INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('6b9609e7-6154-4ace-a6e9-182cf0a80ef3', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '030cde89-bd55-4d78-a3f2-3acaf1e59391', 'aspose-pdf-for-jasperreports', 'Aspose.Pdf for JasperReports', 'Aspose.PDF for JasperReports seamlessly integrates with JasperServer and JasperReports, extending functionality to offer developers flexibility in reports.', 'Aspose.PDF for JasperReports provides developers with a comprehensive solution for generating and exporting reports in various formats with unmatched ease and precision. Whether it''s transforming JRXML reports into PDF or exporting to Microsoft PowerPoint, Aspose.PDF for JasperReports offers a seamless experience, ensuring high fidelity and hassle-free deployment. Input Formats: Developers can leverage Aspose.PDF for JasperReports to process JRXML reports effortlessly. This compatibility means no need for customisations or modifications to existing reports, streamlining the conversion process and saving valuable time. Any report designer supporting JRXML can be utilised to export to PDF, resulting in reports tailored to the specific output requirements of developers. Output Formats: The versatility of Aspose.PDF for JasperReports extends to its output formats,…', ARRAY['JasperReports']::text[], ARRAY['Aspose','Document Automation','JasperReports']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.PDF-for-JasperReports.png","mainImage":"assets/catalog/icons/Aspose.PDF-for-JasperReports.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-pdf-for-jasperreports"}'::jsonb, '{"metaTitle":"Aspose.Pdf for JasperReports | Greatstone International","metaDescription":"Aspose.PDF for JasperReports seamlessly integrates with JasperServer and JasperReports, extending functionality to offer developers flexibility in reports.","socialImage":""}'::jsonb, now());
