INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('480b4978-6763-45db-9fa8-d5aad840fdf0', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'd9850036-dcac-428f-9521-78346e13d26c', 'aspose-pdf-for-java', 'Aspose.PDF for Java', 'Aspose.PDF for Java is an API for processing PDF files, empowering Java applications to Read, Write, Edit, Automate, and Manipulate PDFs without Adobe Acrobat.', 'Aspose.PDF for Java is a robust developer tool empowering users to Create, Manipulate, Read, and Write PDF documents seamlessly. It facilitates the management and dynamic filling of embedded forms in PDFs without requiring Adobe Acrobat. Supported Document Formats encompass a wide range, including PostScript (PS), CGM, MHT, PCL, MD, XSLFO, with Input/Output support for Fixed Layout (PDF, XPS), Books (EPUB), Web formats (HTML, MHTML), and others such as TEX, XML, and SVG. Supported Document Formats: Creating PDFs using Aspose.PDF for Java is straightforward, whether through its API or XML templates. Furthermore, conversion functionalities extend to transforming PDF documents into PowerPoint, Word, or HTML formats. Each page of a PDF can be converted into raster and vector image formats like JPEG, BMP, GIF, EPS, and PNG, while entire documents or specific elements can…', ARRAY['Java']::text[], ARRAY['Aspose','PDF','Java']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.PDF-for-Java.png","mainImage":"assets/catalog/icons/Aspose.PDF-for-Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-pdf-for-java"}'::jsonb, '{"metaTitle":"Aspose.PDF for Java | Greatstone International","metaDescription":"Aspose.PDF for Java is an API for processing PDF files, empowering Java applications to Read, Write, Edit, Automate, and Manipulate PDFs without Adobe Acrobat.","socialImage":""}'::jsonb, now());
