INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('ef5422d1-9441-4c09-95fb-c11d28798fdb', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '030cde89-bd55-4d78-a3f2-3acaf1e59391', 'aspose-pdf-for-reporting-services', 'Aspose.Pdf for Reporting Services', 'Aspose.Pdf for Reporting Services', 'Aspose.PDF for Reporting Services is a comprehensive SSRS rendering extension that gives developers a robust platform the need to build bespoke reporting and business intelligence solutions for generating PDF/A, PDF and XPS reports from Microsoft SSRS. The Aspose.PDF for Reporting Services API supports all RDL report features including, specifying security constraints, adding corresponding XMP metadata to output PDF documents, specifying page orientation within reports, Add footnotes & endnotes for text boxes, tables, charts, images and a lot more. These features ensure PDF and XPS files are generated with the highest quality and accuracy to the main report design. Widely used commonly fixed-layout formats are supported by Aspose.PDF for Reporting Services. Aspose.PDF for Reporting Services Input Formats RDL HTML Aspose.PDF for Reporting Services Output Formats PDF…', ARRAY['Reporting Services']::text[], ARRAY['Aspose','Document Automation','Reporting Services']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.PDF-for-Reporting-Services.png","mainImage":"assets/catalog/icons/Aspose.PDF-for-Reporting-Services.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-pdf-for-reporting-services"}'::jsonb, '{"metaTitle":"Aspose.Pdf for Reporting Services | Greatstone","metaDescription":"Aspose.Pdf for Reporting Services","socialImage":""}'::jsonb, now());
