INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('caf233ae-b15c-4f0a-8a94-2c920c50ea25', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'd9850036-dcac-428f-9521-78346e13d26c', 'aspose-pdf-for-sharepoint', 'Aspose.Pdf for SharePoint', 'Aspose.Pdf for SharePoint', 'Aspose.PDF for SharePoint allows exporting Wiki page, lists and individual list items to the popular PDF file format. The Aspose.PDF for SharePoint library is designed to be natively used with Microsoft s SharePoint Foundation and SharePoint Server. Aspose.PDF for SharePoint Input and Output Formats: Fixed Layout: PDF, PDF/A High-Quality Export to PDF Documents The Aspose.PDF for SharePoint API allows developers to export Wiki pages and list items directly to the popular PDF format with the highest quality; the exported PDF documents are converted. The output document looks the same as the source web page. No need for Adobe Acrobat Automation The Aspose.PDF for SharePoint library is built entirely with managed code such that developers can install and deploy their solutions as a single SharePoint app without requiring Adobe Acrobat automation. It is a lot more robust…', ARRAY['SharePoint']::text[], ARRAY['Aspose','PDF','SharePoint']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.PDF-for-SharePoint.png","mainImage":"assets/catalog/icons/Aspose.PDF-for-SharePoint.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-pdf-for-sharepoint"}'::jsonb, '{"metaTitle":"Aspose.Pdf for SharePoint | Greatstone","metaDescription":"Aspose.Pdf for SharePoint","socialImage":""}'::jsonb, now());
