INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('bfcece03-10cc-4f4b-bef2-33687f7ceeb6', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'ecdf7e8e-bdf3-4009-97f6-e391275375fe', 'aspose-psd-for-java', 'Aspose.PSD for Java', 'Aspose.PSD for Java', 'Aspose.PSD for Java is a comprehensive entry-level AI and PSD and file formats manipulation and automation API without any requiring Adobe Photoshop or Adobe Illustrator. The API allows developers to edit and create Photoshop files and provide the capability to add watermarks, update layer properties, perform graphics operations, and cross-convert files. The Aspose.PSD for Java API supports layer import and export to many formats, including Tiff, Psd, Png, Jpeg, Jpeg2000, Gif, Bmp, Psb, and PDF with the ability to select text. The Aspose.PSD library supports some of Adobe Photoshop features like Text Layer rendering and editing, Adjustment Layers, Layers Effects, Fill Layers, Editing of Raster, and Vector Masks for layers. Aspose.PSD Input/Output Formats Photoshop: PSD, PSB Aspose.PSD Output Formats Raster Formats: TIFF, JPEG, PNG, GIF, BMP, JPEG2000 Other: PDF…', ARRAY['Java']::text[], ARRAY['Aspose','Imaging & Graphics','Java']::text[], 'published', false, 'license', 43500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.PSD-for-Java.png","mainImage":"assets/catalog/icons/Aspose.PSD-for-Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-psd-for-java"}'::jsonb, '{"metaTitle":"Aspose.PSD for Java | Greatstone","metaDescription":"Aspose.PSD for Java","socialImage":""}'::jsonb, now());
