INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('6e648652-dd05-4224-ba9b-d87baecf2cc0', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '2fe5cc38-257e-4d85-8e11-6417e09976c5', 'aspose-slides-for--net', 'Aspose.Slides for .NET', 'Aspose.Slides for .NET', 'Aspose.Slides for .NET is a document Presentation Automation Library for MSPowerPoint and OpenOffice formats. The API enables developers to build applications to protect, read, write, convert, and modify presentations in .NET. Other features include Manage presentation shapes, text, tables, charts, animations, add video & audio to presentations, and preview slides. All of the popular presentation file formats are fully supported. Programmatically split, merge, clone, and reuse multiple MSPowerPoint presentations, slides, and templates in multiple ways. The Aspose.Slides API offers advanced automation features for printing on physical printers, rendering presentations to HTML & images, and fixed-layout formats. It does not require Microsoft PowerPoint or any other 3rd party library. Aspose.Slides Input/Output Formats OpenOffice: ODP Microsoft PowerPoint: PPT, PPSX,…', ARRAY['.NET']::text[], ARRAY['Aspose','Presentations','.NET']::text[], 'published', false, 'license', 72500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Slides-for-.NET.png","mainImage":"assets/catalog/icons/Aspose.Slides-for-.NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-slides-for--net"}'::jsonb, '{"metaTitle":"Aspose.Slides for .NET | Greatstone","metaDescription":"Aspose.Slides for .NET","socialImage":""}'::jsonb, now());
