INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('b7101211-25a8-4f2d-b3c9-4de202e1a119', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '2fe5cc38-257e-4d85-8e11-6417e09976c5', 'aspose-slides-for-c++', 'Aspose.Slides for C++', 'Aspose.Slides for C++', 'Aspose.Slides for C++ is a feature-rich PowerPoint automation library for the manipulating, rendering & conversion of PPT and PPTX formats in C++ without requiring Microsoft PowerPoint or MSOffice automation. The API supports high fidelity rendering of slides to many popular graphics formats. It provides the functionality to create or modify many file elements of files, format shapes and text on slides and a lot more. Aspose.Slides for C++ support many slideshows and PowerPoint formats including PPTX, PPSX, POT, PPT, PPS, POTX, ODP and many more. Developers can also use Aspose.Slides for C++ to convert these formats to PDF, HTML, XPS and more. Aspose.Slides for C++ Input and Output formats: Microsoft PowerPoint: PPT, POT, PPS, PPTX, POTX, PPSX, PPTM, PPSM, POTM OpenOffice: ODP Open Document: OTP Others: TIFF, EMF, XML Aspose.Slides for C++ Output formats Fixed…', ARRAY['C++']::text[], ARRAY['Aspose','Presentations','C++']::text[], 'published', false, 'license', 72500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Slides-for-C__.png","mainImage":"assets/catalog/icons/Aspose.Slides-for-C__.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-slides-for-c++"}'::jsonb, '{"metaTitle":"Aspose.Slides for C++ | Greatstone","metaDescription":"Aspose.Slides for C++","socialImage":""}'::jsonb, now());
