INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('8cbd02b9-969f-4ba9-90f9-e527bd72bdbc', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '030cde89-bd55-4d78-a3f2-3acaf1e59391', 'aspose-slides-for-jasperreports', 'Aspose.Slides for JasperReports', 'Aspose.Slides for JasperReports', 'Aspose.Slides for JasperReports is a PowerPoint developer library API for versatile exports of JasperServer, and JasperReports reports to PowerPoint. JasperServer does not have native capabilities to export reports as PowerPoint presentations. With this PowerPoint API, JasperServer reports can be exported to PPS, PPT, PPSX and PPTX presentation formats without requiring Microsoft PowerPoint. Aspose.Slides for JasperReports Output Formats Microsoft PowerPoint: PPT, PPTX, PPS, PPSX Others: PDF, HTML Multiple Axis Chart Report Support Aspose.Slides for JasperReports supports exporting complicated reports with MultipleAxisChartReport to Microsoft PowerPoint presentations. The output is identical to the original as it appears in the JasperViewer. Export Reports to Presentation Formats JasperServer and JasperReports do not have the native support for exporting reports to…', ARRAY['JasperReports']::text[], ARRAY['Aspose','Document Automation','JasperReports']::text[], 'published', false, 'license', 72500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Slides-for-JasperReports.png","mainImage":"assets/catalog/icons/Aspose.Slides-for-JasperReports.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-slides-for-jasperreports"}'::jsonb, '{"metaTitle":"Aspose.Slides for JasperReports | Greatstone","metaDescription":"Aspose.Slides for JasperReports","socialImage":""}'::jsonb, now());
