INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('af30bfa7-7a3b-459d-a155-f6edfd620ef6', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '2fe5cc38-257e-4d85-8e11-6417e09976c5', 'aspose-slides-for-java', 'Aspose.Slides for Java', 'Aspose.Slides for Java', 'Aspose.Slides for Java is a document Presentation Automation Library for MSPowerPoint and OpenOffice formats. The API enables developers to build applications to protect, read, write, convert, and modify presentations in Java. Other features include Manage presentation shapes, text, tables, charts, animations, add video & audio to presentations, and preview slides. All of the popular presentation file formats are fully supported. Programmatically split, merge, clone, and reuse multiple MSPowerPoint presentations, slides, and templates in multiple ways. The Aspose.Slides API offers advanced automation features for printing on physical printers, rendering presentations to HTML & images, and fixed-layout formats. It does not require Microsoft PowerPoint or any other 3rd party library. Aspose.Slides Input/Output Formats OpenOffice: ODP Microsoft PowerPoint: PPT, PPSX,…', ARRAY['Java']::text[], ARRAY['Aspose','Presentations','Java']::text[], 'published', false, 'license', 72500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Slides-for-Java.png","mainImage":"assets/catalog/icons/Aspose.Slides-for-Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-slides-for-java"}'::jsonb, '{"metaTitle":"Aspose.Slides for Java | Greatstone","metaDescription":"Aspose.Slides for Java","socialImage":""}'::jsonb, now());
