INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('b09c999d-54e3-4130-ac5a-020597cf683c', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '030cde89-bd55-4d78-a3f2-3acaf1e59391', 'aspose-slides-for-reporting-services', 'Aspose.Slides for Reporting Services', 'Aspose.Slides for Reporting Services', 'Aspose.Slides for Reporting Services a unique solution that makes generating presentations in PowerPoint''s native formats from within the Microsoft SQL Server Reporting Services possible. Aspose.Slides for Reporting Services supports RDL features like lists, tables, matrices, charts, images, sub-reports & header/footers allowing developers to export reports in PowerPoint presentation formats that they appear identical to the original report design. Developers can also perform Reporting Services SQL PPT without Microsoft PowerPoint Automation. Aspose.Slides for Reporting Services Input Formats: RDL RPL Aspose.Slides for Reporting Services Output Formats: PPT PPTX PPS PPSX XPS Export Reports to Slideshow & Presentation Formats SQL Server Reporting Services does not provide native support for exporting RDL reports to PowerPoint Presentations or slideshows. Developers…', ARRAY['Reporting Services']::text[], ARRAY['Aspose','Document Automation','Reporting Services']::text[], 'published', false, 'license', 72500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Slides-for-Reporting-Services.png","mainImage":"assets/catalog/icons/Aspose.Slides-for-Reporting-Services.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-slides-for-reporting-services"}'::jsonb, '{"metaTitle":"Aspose.Slides for Reporting Services | Greatstone","metaDescription":"Aspose.Slides for Reporting Services","socialImage":""}'::jsonb, now());
