INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('b2c6b769-614f-4a37-8621-8cc836bd60dc', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '2fe5cc38-257e-4d85-8e11-6417e09976c5', 'aspose-slides-for-sharepoint', 'Aspose.Slides for SharePoint', 'Aspose.Slides for SharePoint', 'Aspose.Slides for SharePoint is a developer library that can convert, manage and automate MSPowerPoint files in SharePoint. This robust SharePoint PowerPoint solution can robustly import popular Microsoft presentation formats including PPTX, PPT, POT, PPS, PPSX & POTX and can export them to TIFF, XPS and PDF formats. Al this without requiring Microsoft PowerPoint Automation. Aspose.Slides for SharePoint support Microsoft Office SharePoint Server 2007, 2010 & 2013 and Windows SharePoint Services WSS 3.0. Aspose.Slides for SharePoint Input and Output formats: Microsoft PowerPoint: PPT, POTX, POTM, PPTX, PPS, PPSX, PPTM, PPSM Aspose.Slides for SharePoint Output formats: Fixed Layout: PDF, XPS Images: TIFF, SVG Web: SWF, HTML PowerPoint Presentations Conversion to Multiple Formats Using the Aspose.Slides for SharePoint API developers can convert MS presentations from…', ARRAY['SharePoint']::text[], ARRAY['Aspose','Presentations','SharePoint']::text[], 'published', false, 'license', 72500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Slides-for-SharePoint.png","mainImage":"assets/catalog/icons/Aspose.Slides-for-SharePoint.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-slides-for-sharepoint"}'::jsonb, '{"metaTitle":"Aspose.Slides for SharePoint | Greatstone","metaDescription":"Aspose.Slides for SharePoint","socialImage":""}'::jsonb, now());
