INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('69bb62a1-838a-4453-9857-119d5524d9ca', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '2fe5cc38-257e-4d85-8e11-6417e09976c5', 'aspose-slides-product-family', 'Aspose.Slides Product Family', 'The Aspose.Slides product suite includes .NET, Java, Android and more APIs and Libraries to generate, manage and convert PowerPoint presentations.', 'With Aspose.Slides Product Family, you can unlock a world of possibilities for your PowerPoint-related development tasks, from simple automation to complex presentation manipulation across a wide range of platforms and technologies. Experience enhanced productivity, seamless integration, and unparalleled performance with Aspose.Slides. Aspose.Slides for .NET : Seamlessly automate the manipulation of PowerPoint presentations in various formats including OOXML, PPTX, ODP, PPT, PPS, and POT within the .NET framework. Aspose.Slides for Java: Gain the ability to protect, read, write, convert, and modify presentations with ease, leveraging the power of Java. Aspose.Slides for C++: Write, read, convert, and process PowerPoint presentations directly within your C++ applications, enhancing efficiency and performance. Aspose.Slides for Android via Java: Harness the…', '{}', ARRAY['Aspose','Presentations']::text[], 'published', false, 'license', 101500, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Slides-Product-Family.png","mainImage":"assets/catalog/icons/Aspose.Slides-Product-Family.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-slides-product-family"}'::jsonb, '{"metaTitle":"Aspose.Slides Product Family | Greatstone International","metaDescription":"The Aspose.Slides product suite includes .NET, Java, Android and more APIs and Libraries to generate, manage and convert PowerPoint presentations.","socialImage":""}'::jsonb, now());
