INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('5b67d5d3-6aa2-49d6-a0c6-3c81305888db', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'ecdf7e8e-bdf3-4009-97f6-e391275375fe', 'aspose-svg-for-net', 'Aspose.SVG for .NET', 'Aspose.SVG for .NET', 'Aspose.SVG for .NET is a versatile development library for processing SVG files with the capability to set a wide array of specifications. Developers can use the API to convert, save, and load SVG files and cycle through and the elements of the SVG file through its Document Object Model (DOM). The API does not require any 3rd party component to work and can Load, Parse and Convert SVG to PDF, XPS, PNG and other popular image formats without interrogating the underlying details of the input file. Aspose.SVG Input Formats SVG Aspose.SVG Output Formats Fixed Layout: PDF, XPS Images: TIFF, BMP, PNG, JPEG, GIF Convert SVG to PNG Developers can the Aspose.SVG for .NET library to Convert and Read SVG files to the popular PDF, XPS, and other widely used image formats. The conversion method is straightforward and is dependent on each solution''s needs.', ARRAY['.NET']::text[], ARRAY['Aspose','Imaging & Graphics','.NET']::text[], 'published', false, 'license', 43500, 'GBP', '{"icon":"assets/catalog/icons/aspose_svg-for-net.png","mainImage":"assets/catalog/icons/aspose_svg-for-net.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-svg-for-net"}'::jsonb, '{"metaTitle":"Aspose.SVG for .NET | Greatstone","metaDescription":"Aspose.SVG for .NET","socialImage":""}'::jsonb, now());
