INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('e3f4bfee-4baa-48d5-ba48-99e53ffe6d21', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', 'f2189fd7-9f71-4345-95b3-29f3eaebd08d', 'aspose-tasks-for--net', 'Aspose.Tasks for .NET', 'Aspose.Tasks for .NET', 'Aspose.Tasks for .NET is a project management API used to process MSProject file formats. Developers can write, read, manipulate, and MSProject documents without any 3rd party software dependency. They can also access project data to manipulate project planning, definition, and tracking. Users are able to define a project''s calendar information and other default tracking elements. Other data, like resource assignments, tasks, resources, and extended attributes data, can also be manipulated or created. The API provides the functionality to build project plans by creating and reading project resources and tasks and remove or assign them to or from other tasks. They are able to manipulate priorities, critical and effort driven tasks, constraints, resume, stop or split tasks, link tasks, and write updated data back to the project and manage extended attributes.…', ARRAY['.NET']::text[], ARRAY['Aspose','Project Management','.NET']::text[], 'published', false, 'license', 58000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Tasks-for-.NET.png","mainImage":"assets/catalog/icons/Aspose.Tasks-for-.NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-tasks-for--net"}'::jsonb, '{"metaTitle":"Aspose.Tasks for .NET | Greatstone","metaDescription":"Aspose.Tasks for .NET","socialImage":""}'::jsonb, now());
