INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('e6e2eaff-1903-4c11-91bf-7116bdda0e9e', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '91f15861-f991-468b-9a13-385390b6d80b', 'aspose-total-for-net', 'Aspose.Total for .NET', 'Aspose.Total for .NET is the most comprehensive .NET component set from Aspose PTY. It includes all the .NET components.', 'Aspose.Total for .NET is the most comprehensive .NET component set from Aspose PTY. It includes all the .NET components provided by the Australian based software developer. The Aspose team compiles Aspose.Total daily to ensure it contains only the most up to date versions of their .NET components. Aspose.Total for .NET provides developers with the functionality to Edit, Render, Build, Convert, Print, and Automate Word, Excel, PDF, PowerPoint, Outlook and more than 100 other file document formats in their .NET, ASP.NET, C#, and VB applications. Aspose.Total for .NET includes the following components: Aspose.Words for .NET Aspose.Words is a .NET API that provides programmers with a vast range of document processing capabilities within their .NET, iOS, macOS & Android applications. Developers can Automate, Modify, Render, Generate, Convert, and Print documents without…', ARRAY['.NET']::text[], ARRAY['Aspose','Suites & Bundles','.NET']::text[], 'published', false, 'license', 290000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Total-for-.NET.png","mainImage":"assets/catalog/icons/Aspose.Total-for-.NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-total-for-net"}'::jsonb, '{"metaTitle":"Aspose.Total for .NET | Greatstone International","metaDescription":"Aspose.Total for .NET is the most comprehensive .NET component set from Aspose PTY. It includes all the .NET components.","socialImage":""}'::jsonb, now());
