INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('9c92a5e5-bc84-4933-8cd7-c684b50135bd', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '91f15861-f991-468b-9a13-385390b6d80b', 'aspose-total-for-c++', 'Aspose.Total for C++', 'Aspose.Total for C++ is a package of components for the creation, manipulation & conversion of popular Microsoft Office & PDF document formats.', 'Aspose.Total for C++ is the most comprehensive C++ component set from Aspose PTY. It includes all the C++ components provided by the Australian based software developer. Aspose.Total for C++ is a package of C++ components for the creation, manipulation & conversion of popular Microsoft Office & PDF document formats without using Adobe Automation or MSOffice. The C++ component suite includes a specialised Barcode recognition with advanced features that can be used to automate the barcode recognition and generation process. Aspose.Total for C++ includes the following components Aspose.Words for C++ Aspose.Words for C++ is a class library that provides programmers with a vast range of document processing capabilities within their C++ applications. Developers can Automate, Modify, Render, Generate, Convert, and Print DOCX, DOCM, DOTX, DOC, DOT, RTF, FlatOPC, DOTM, TXT,…', ARRAY['C++']::text[], ARRAY['Aspose','Suites & Bundles','C++']::text[], 'published', false, 'license', 290000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Total-for-C__.png","mainImage":"assets/catalog/icons/Aspose.Total-for-C__.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-total-for-c++"}'::jsonb, '{"metaTitle":"Aspose.Total for C++ | Aspose | Greatstone International","metaDescription":"Aspose.Total for C++ is a package of components for the creation, manipulation & conversion of popular Microsoft Office & PDF document formats.","socialImage":""}'::jsonb, now());
