INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('0e91c543-2f3d-444f-ade5-ecf20a857fdb', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '91f15861-f991-468b-9a13-385390b6d80b', 'aspose-total-for-java', 'Aspose.Total for Java', 'Aspose.Total for Java is the most comprehensive Java component set from Aspose PTY, including all the Java components they offer.', 'Aspose.Total for Java is the most comprehensive Java component set from Aspose PTY. It includes all the Java components provided by the Australian based software developer. The Aspose team compiles Aspose.Total daily to ensure it contains only the most up to date versions of their Java components. Aspose.Total for Java provides developers with the functionality to Edit, Render, Build, Convert, Print, and Automate Word, Excel, PDF, PowerPoint, Outlook and more than 100 other file document formats in their Java J2SE, J2EE and J2ME applications. Aspose.Total for Java includes the following components: Aspose.Words for Java Aspose.Words is a Java API that provides programmers with a vast range of document processing capabilities within their Java, iOS, macOS & Android applications. Developers can Automate, Modify, Render, Generate, Convert, and Print documents without…', ARRAY['Java']::text[], ARRAY['Aspose','Suites & Bundles','Java']::text[], 'published', false, 'license', 290000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Total-for-Java.png","mainImage":"assets/catalog/icons/Aspose.Total-for-Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-total-for-java"}'::jsonb, '{"metaTitle":"Aspose.Total for Java | Aspose | Greatstone International","metaDescription":"Aspose.Total for Java is the most comprehensive Java component set from Aspose PTY, including all the Java components they offer.","socialImage":""}'::jsonb, now());
