INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('0e63b250-9cce-4778-aca0-099c5e76933c', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '347c33ef-802b-4221-8d97-4b1e532ce158', 'aspose-words-for-android-via-java', 'Aspose.Words for Android via Java', 'Aspose.Words for Android via Java is a robust document processing library that helps developers to perform document automation and manipulation tasks.', 'Aspose.Words for Android via Java is a robust document processing library that provides developers with the ability to perform document automation and manipulation tasks within their Android applications. The API allows developers to programmatically convert, create, manipulate and render Microsoft Word files. The Aspose.Words for Android via Java API provides support for the processing of MS Word native formats like TXT, DOC, DOCX, OOXML, RTF and various commonly used formats, for example, EPUB, XPS, HTML, OpenDocument ODT, PDF and image formats including SVG, EMF, JPEG and PNG. Aspose.Words for Android via Java Input and Output formats: Microsoft Word: DOC, DOCX, RTF, DOT, DOTX, DOTM, DOCM FlatOPC, FlatOpcMacroEnabled, FlatOpcTemplate, FlatOpcTemplateMacroEnabled OpenOffice: ODT, OTT WordprocessingML: WordML Web: HTML, MHTML Text: TXT Aspose.Words for Android via…', ARRAY['Java','Android']::text[], ARRAY['Aspose','Word Processing','Java','Android']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Words-for-Android-via-Java.png","mainImage":"assets/catalog/icons/Aspose.Words-for-Android-via-Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-words-for-android-via-java"}'::jsonb, '{"metaTitle":"Aspose.Words for Android via Java | Greatstone International","metaDescription":"Aspose.Words for Android via Java is a robust document processing library that helps developers to perform document automation and manipulation tasks.","socialImage":""}'::jsonb, now());
