INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('ebe34f52-9ab8-4c53-9ef1-cbf8de1e4776', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '030cde89-bd55-4d78-a3f2-3acaf1e59391', 'aspose-words-for-jasperreports', 'Aspose.Words for JasperReports', 'Aspose.Words for JasperReports is a unique solution that makes it possible to export reports to various formats without requiring MSWord.', 'Aspose.Words for JasperReports is a unique solution that makes it possible to export reports from and JasperServer and JasperReports to OpenDocument Text (ODT), Web page (HTML), Microsoft Word document (DOC), Office Open XML (OOXML, DOCX), Rich Text Format (RTF), and plain text (TXT) formats without requiring MSWord. All report features with the highest fidelity can be converted to Microsoft Word file. Aspose.Words for JasperReports Output Formats: Microsoft Word: DOC, DOCX, RTF OpenOffice: ODT Web: HTML Text: TXT Support for Most Popular Microsoft Word Formats The Aspose.Words for JasperReports library allows developers to export reports as DOCX and DOC documents from JasperServer and JasperReports. Compared to RTF, these formats offer many advantages, including increased content formatting, smaller file size, and seamless editing. RTF, ODT, HTML and TXT formats can…', ARRAY['JasperReports']::text[], ARRAY['Aspose','Document Automation','JasperReports']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Words-for-JasperReports.png","mainImage":"assets/catalog/icons/Aspose.Words-for-JasperReports.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-words-for-jasperreports"}'::jsonb, '{"metaTitle":"Aspose.Words for JasperReports | Greatstone International","metaDescription":"Aspose.Words for JasperReports is a unique solution that makes it possible to export reports to various formats without requiring MSWord.","socialImage":""}'::jsonb, now());
