INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('25772553-3d8e-431f-94f1-21b5edb7dc44', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '347c33ef-802b-4221-8d97-4b1e532ce158', 'aspose-words-for-java', 'Aspose.Words for Java', 'Aspose.Words is a Java API that provides programmers with a vast range of document processing capabilities within their Java applications.', 'Aspose.Words is a Java API that provides programmers with a vast range of document processing capabilities within their Java applications. Developers can Automate, Modify, Render, Generate, Convert, and Print documents without using Microsoft s Word processing suite MS Word. Aspose.Words supports many popular document formats, including DOC, OOXML, RTF, HTML, OpenDocument, PDF, XPS, EPUB. Aspose.Words for Java is a Word format automation API that enables developers to perform an expansive number of tasks from their Java applications. Developers can View, Generate, Modify, Convert, Render, and Print documents and files without using Microsoft Word. Supported Document Formats Aspose.Words Input/Output Formats Microsoft Word: DOC, DOCX, RTF, DOT, DOTX, DOTM, DOCM FlatOPC, FlatOpcMacroEnabled, FlatOpcTemplate, FlatOpcTemplateMacroEnabled OpenOffice: ODT, OTT…', ARRAY['Java']::text[], ARRAY['Aspose','Word Processing','Java']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Words-for-Java.png","mainImage":"assets/catalog/icons/Aspose.Words-for-Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-words-for-java"}'::jsonb, '{"metaTitle":"Aspose.Words for Java | Aspose | Greatstone International","metaDescription":"Aspose.Words is a Java API that provides programmers with a vast range of document processing capabilities within their Java applications.","socialImage":""}'::jsonb, now());
