INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('0b288812-e495-4fc9-ab63-b7f953c867b4', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '030cde89-bd55-4d78-a3f2-3acaf1e59391', 'aspose-words-for-reporting-services', 'Aspose.Words for Reporting Services', 'Aspose.Words for Reporting Services is an SSRS rendering extension that provides developers with the ability to export reports as various file formats.', 'Aspose.Words for Reporting Services is an SSRS rendering extension that provides developers with the capability to export RDLC, and RDL reports as RTF, HTML, DOC, DOCX, PDF, and MHTML ODT, TXT, WordprocessingML and XPS files from Microsoft SQL Server Reporting Services. The Aspose.Words for Reporting Services API completely supports all RDL specifications. Developers can use any report designer to redesign existing reports or export existing RDL reports as a Microsoft Word document and render the output document such that it is identical to the RDL design. Developers can use the library to output documents and files to widely popular word processing and meta language formats. Aspose.Words for Reporting Services Input Only Formats RDL RDLC Aspose.Words for Reporting Services Output Only Formats Microsoft Word: DOC, DOCX, RTF OpenOffice: ODT Fixed Layout: PDF, XPS Web:…', ARRAY['Reporting Services']::text[], ARRAY['Aspose','Document Automation','Reporting Services']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Words-for-Reporting-Services.png","mainImage":"assets/catalog/icons/Aspose.Words-for-Reporting-Services.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-words-for-reporting-services"}'::jsonb, '{"metaTitle":"Aspose.Words for Reporting Services | Greatstone","metaDescription":"Aspose.Words for Reporting Services is an SSRS rendering extension that provides developers with the ability to export reports as various file formats.","socialImage":""}'::jsonb, now());
