INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('50147406-5048-48c3-a5b6-9391a2e1ae2e', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '347c33ef-802b-4221-8d97-4b1e532ce158', 'aspose-words-for-sharepoint', 'Aspose.Words for SharePoint', 'Aspose.Words for SharePoint makes it possible to combine and convert word documents within MS SharePoint applications. Available from Greatstone International.', 'Aspose.Words for SharePoint makes it possible to combine and convert word documents within MS SharePoint applications. High fidelity conversion, as well as the concatenation of multiple files during conversion, is supported. The library can generate reports based on Microsoft Word template documents with dynamic data from XML files, SQL databases or SharePoint lists. Aspose.Words for SharePoint Input and Output formats: Microsoft Word: DOC, DOCX, RTF OpenOffice: ODT Web: MHT Text: TXT Aspose.Words for SharePoint Output formats: Fixed Layout: PDF, XPS Others: EPUB, XML, FlatOpc Word Documents conversion to Multiple File Formats The Aspose.Words for SharePoint library gives developers the capability to convert supported documents to and from many popular office document formats directly within SharePoint s document library. The conversions are performed with extremely…', ARRAY['SharePoint']::text[], ARRAY['Aspose','Word Processing','SharePoint']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.Words-for-SharePoint.png","mainImage":"assets/catalog/icons/Aspose.Words-for-SharePoint.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-words-for-sharepoint"}'::jsonb, '{"metaTitle":"Aspose.Words for SharePoint | Greatstone International","metaDescription":"Aspose.Words for SharePoint makes it possible to combine and convert word documents within MS SharePoint applications. Available from Greatstone International.","socialImage":""}'::jsonb, now());
