INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('d3ffa74a-6215-4b36-afc1-dd780c641365', '11111111-1111-4111-8111-111111111111', 'product', '00a1aaa7-aee0-4466-b2b4-2e4205534017', '91301607-b61c-4dd5-8dcd-3f778ae0afe2', 'aspose-zip-for--net', 'Aspose.ZIP for .NET', 'Aspose.ZIP for .NET', 'Aspose.ZIP for .NET is a versatile document manipulation, archiving, and compression API for the popular ZIP format. The API gives developers the ability to build .NET applications to achieve file archiving, decompression, and compression, as well as the encryption and management of archives. It enables encryption through user-defined passwords and traditional encryption using AES or ZipCrypto encryption like AES128, 192, and AES256. Aspose.ZIP Input Formats Decompression: ZIP, TAR, GZIP, BZ2 Compression: Files, Archives Aspose.ZIP Output Formats Decompressed: Files, Archives Compressed: ZIP, TAR, GZIP, BZ2 Compression API Integration in .NET Applications The integration of a compression library using Aspose.ZIP is straightforward and enables developers to perform all decompression & compression tasks with a few lines of code.', ARRAY['.NET']::text[], ARRAY['Aspose','Archiving & Compression','.NET']::text[], 'published', false, 'license', 58000, 'GBP', '{"icon":"assets/catalog/icons/Aspose.ZIP-for-.NET.png","mainImage":"assets/catalog/icons/Aspose.ZIP-for-.NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/aspose/aspose-zip-for--net"}'::jsonb, '{"metaTitle":"Aspose.ZIP for .NET | Greatstone","metaDescription":"Aspose.ZIP for .NET","socialImage":""}'::jsonb, now());
