INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('2d5fee3b-1506-4eb5-b75f-e8f4f0dd2dcb', '11111111-1111-4111-8111-111111111111', 'product', '5a3d5c2b-a9ec-4dca-8a3d-358605682087', '9caccbf0-bfd0-4ffb-b834-f5f5be83ef17', 'devexpress-asp-net', 'DevExpress ASP.NET', 'DevExpress’s ASP.NET developer suite includes more than 110 UI controls & components for ASP.NET and all you need to build Office-style applications.', 'DevExpress s ASP.NET developer suite ships with more than 110 User Interface controls and components for ASP.NET (including Reporting), Server-Side MVC extensions or Clientside controls, and all developers need to build Office-style applications. The DevExpress ASP.NET Subscription installs with more than 70 high-performance ASP.NET Core User Interface controls that developers can use to build and design immersive user experiences for Server-Side (Razor Components) and Clientside (Blazor) platforms and a JavaScript component suite for responsive web development. Also included is ASP.NET Bootstrap Controls for Office-driven and Data Visualisation applications and Blazor Components (including a Data Grid and Pivot Grid), ASP.NET controls, JavaScript Widgets, ASP.NET Core, ASP.NET MVC, jQuery, Angular, React, and Vue Apps. DevExpress ASP.NET includes: ASP.NET Web Forms…', ARRAY['.NET']::text[], ARRAY['DevExpress','UI Components','.NET']::text[], 'published', false, 'license', 68000, 'GBP', '{"icon":"assets/catalog/icons/DevExpress-ASP.NET-20.1.png","mainImage":"assets/catalog/icons/DevExpress-ASP.NET-20.1.png","gallery":["https://www.greatstonesoftware.co.uk/storage/gallery/cropped/devexpress-aspnet-calendar-app.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/devexpress-aspnet-charts-dashboard.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/devexpress-aspnet-contacts-app.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/devexpress-aspnet-grid-charting.png"],"sourceUrl":"https://www.greatstonesoftware.co.uk/devexpress/devexpress-asp-net"}'::jsonb, '{"metaTitle":"DevExpress ASP.NET | UI Controls | Greatstone International","metaDescription":"DevExpress’s ASP.NET developer suite includes more than 110 UI controls & components for ASP.NET and all you need to build Office-style applications.","socialImage":""}'::jsonb, now());
