INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('3e24e993-2088-48c3-b9fa-eec61a05f5ce', '11111111-1111-4111-8111-111111111111', 'product', '5a3d5c2b-a9ec-4dca-8a3d-358605682087', '9caccbf0-bfd0-4ffb-b834-f5f5be83ef17', 'devexpress-devextreme', 'DevExpress DevExtreme', 'DevExpress DevExtreme includes a complete set of high-performance UI widgets from Angular and React, to ASP.NET Core or Vue for web and mobile applications.', 'DevExtreme includes a complete set of high-performance UI widgets from Angular and React, to ASP.NET Core or Vue for conventional web and next-generation Mobile applications. The DevExtreme Subscription ships with feature-rich Interactive Charts Widgets, Data Editors, Data Grid and a lot more. DevExtreme helps developers deliver remarkable end-user experiences for every modern web browser. DevExpress DevExtreme Includes: ASP.NET Core ASP.NET MVC jQuery, Angular, React, and Vue Apps Data Grid Reporting Charting HTML / Markdown Editor Calendar & Scheduling Pivot Grid Tree List Diagram Gantt Navigation & Layout Dialogs & Notifications Map Control Gauge Controls File Management Controls Form Layout Data Editors Export Library', '{}', ARRAY['DevExpress','UI Components']::text[], 'published', false, 'license', 55100, 'GBP', '{"icon":"assets/catalog/icons/DevExtreme-JavaScript.png","mainImage":"assets/catalog/icons/DevExtreme-JavaScript.png","gallery":["https://www.greatstonesoftware.co.uk/storage/gallery/cropped/DevExpress-HTML-JS-Form-Layout-Editor.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/DevExpress-HTML-JS-Server-Health-Monitor.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/DevExpress-HTML-JS-Stock-Market.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/devextreme-sales-viewer-customers.png"],"sourceUrl