INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('fcc7a259-e0fe-4971-bb00-fdde26481a4d', '11111111-1111-4111-8111-111111111111', 'product', '5a3d5c2b-a9ec-4dca-8a3d-358605682087', '9d330959-4ebe-4a86-ada1-e41769d12793', 'testcafe-studio', 'DevExpress TestCafe Studio', 'DevExpress TestCafe Studio is a light, rapid and dependable test automation solution that does not rely on any third party tools or components. ', 'DevExpress TestCafe Studio is a light, rapid and dependable test automation solution. The test solution does not rely on browser plugins, a WebDriver or any 3rd party tools or components. Developers just need to install it can start testing straight away. Tests can run on all popular browsers desktops, mobile and cloud, with or without a User Interface. DevExpress TestCafe Includes the following features and capabilities: Quick and easy installation No WebDriver, plugins or extra tools Tests can run across all popular browsers: desktop, mobile and cloud, with UI or headless Integrated Visual Test Recorder Intelligent Wait Mechanism: No Need for Manual Timeouts Test Debugging Automatic Selector Generation Algorithm Integrated IDE to Record, Edit, Run Tests, and Analyze Results', '{}', ARRAY['DevExpress','Testing & QA']::text[], 'published', false, 'license', 30600, 'GBP', '{"icon":"assets/catalog/icons/DevExpress-TestCafe.png","mainImage":"assets/catalog/icons/DevExpress-TestCafe.png","gallery":["https://www.greatstonesoftware.co.uk/storage/gallery/cropped/devexpress-testcafe-environment.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/devexpress-testcafe-save-time-with-auto-selectors.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/devexpress-testcafe-test-recorder.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/devexpress-testcafe-test-run.png"],"sourceUrl":"https://www.greatstonesoftware.co.uk/devexpress/testcafe-studio"}'::jsonb, '{"metaTitle":"DevExpress TestCafe Studio | Greatstone International","metaDescription":"DevExpress TestCafe Studio is a light, rapid and dependable test automation solution that does not rely on any third party tools or components. ","socialImage":""}'::jsonb, now());
