INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('c9613dd8-e715-4498-9a3e-a6e5e64ca0ad', '11111111-1111-4111-8111-111111111111', 'product', 'f87702fd-418c-4b91-a827-997c410da59e', '9d09545a-9d46-47c3-8390-efe828471d91', 'groupdocs-annotation-for-java', 'GroupDocs.Annotation for Java', 'GroupDocs.Annotation for Java', 'GroupDocs.Annotation for Java is an all-inclusive group of APIs that developers can use to create document annotation management applications in Java. They can create various annotation types including polyline, arrow, distance, watermark, image etc. for PDF, HTML, area, point, text, ellipse, link, underline, Microsoft Office Word, Visio, images, CAD drawing, Excel spreadsheets, PowerPoint presentations and other formats. This library allows a developer to export documents after annotating back to its original format for further processing and provides a useful group of data objects that developers can use to further customise annotations. GroupDocs.Annotation for Java supported formats: Microsoft Office Formats Microsoft PowerPoint: POTX, POTM, PPSM, PPS, PPSX PPT, PPTX, PPTM Microsoft Visio: VSD, VSS, VSDX, VST Microsoft Word: DOC, DOT, DOTX, RTF, DOCX, DOCM…', ARRAY['Java']::text[], ARRAY['GroupDocs','Annotation','Java']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/GroupDocs.Annotation_for_Java.png","mainImage":"assets/catalog/icons/GroupDocs.Annotation_for_Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/groupdocs/groupdocs-annotation-for-java"}'::jsonb, '{"metaTitle":"GroupDocs.Annotation for Java | Greatstone","metaDescription":"GroupDocs.Annotation for Java","socialImage":""}'::jsonb, now());
