INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('ae102ba8-a373-416b-bfd9-7f8304c0fa0f', '11111111-1111-4111-8111-111111111111', 'product', 'f87702fd-418c-4b91-a827-997c410da59e', '030cde89-bd55-4d78-a3f2-3acaf1e59391', 'groupdocs-assembly-for--net', 'GroupDocs.Assembly for .NET', 'GroupDocs.Assembly for .NET', 'The GroupDocs.Assembly for .NET API is a developer toolkit to build robust document automation and report creation applications to build reports from bespoke templates in .NET applications. With a couple of code lines developers can intelligently assemble data from a given document template and generate intelligent and rich reports in the chosen output format by retrieving data from multiple data sources, for example, JSON, ODATA, CSV, databases, XML and Custom .NET objects). The library supports LINQ-based template syntax, and can y generate documents to formats including Microsoft Office Word, Excel worksheets, PDF, HTML, Outlook email, PowerPoint presentations. Formatting properties for elements on a template can be configured by manipulating HTML & conditional blocks, text, barcodes, hyperlinks, images, charts, pivot tables and more. Microsoft Office Formats…', ARRAY['.NET']::text[], ARRAY['GroupDocs','Document Automation','.NET']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/GroupDocs.Assembly_for_NET.png","mainImage":"assets/catalog/icons/GroupDocs.Assembly_for_NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/groupdocs/groupdocs-assembly-for--net"}'::jsonb, '{"metaTitle":"GroupDocs.Assembly for .NET | Greatstone","metaDescription":"GroupDocs.Assembly for .NET","socialImage":""}'::jsonb, now());
