INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('acf82cff-61bc-4b1d-9a81-a262df6cbb37', '11111111-1111-4111-8111-111111111111', 'product', 'f87702fd-418c-4b91-a827-997c410da59e', '030cde89-bd55-4d78-a3f2-3acaf1e59391', 'groupdocs-classification-for--net', 'GroupDocs.Classification for .NET', 'GroupDocs.Classification for .NET', 'GroupDocs.Classification for .NET is a versatile developer API used to build text and document classification/categorisation applications. The API supports four unique taxonomies types and has sophisticated document and text classification by using IAB-2 for designating standardised text categories, Documents taxonomy for a large number of document formats, or Sentiment (and Sentiment3) for the sentiment analysis. The library analyses text, sentences, words, and supports classifying various industry-standard document formats including Microsoft Word, OpenDocument, RTF, PDF and TXT. Sentiment analysis (classification) supports Chinese, Spanish, English and German auto-detection or languages. Using its native document processing/classification engine, GroupDocs.Classification for .NET does not need any components to work. It works on the .NET platform and supports…', ARRAY['.NET']::text[], ARRAY['GroupDocs','Document Automation','.NET']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/groupdocs_classification-for-net.png","mainImage":"assets/catalog/icons/groupdocs_classification-for-net.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/groupdocs/groupdocs-classification-for--net"}'::jsonb, '{"metaTitle":"GroupDocs.Classification for .NET | Greatstone","metaDescription":"GroupDocs.Classification for .NET","socialImage":""}'::jsonb, now());
