INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('75095dd6-c7e5-4b13-9171-77fcb0587e88', '11111111-1111-4111-8111-111111111111', 'product', 'f87702fd-418c-4b91-a827-997c410da59e', 'ebca3b93-ac0b-407c-a7cb-b5694705456a', 'groupdocs-editor-for--net', 'GroupDocs.Editor for .NET', 'GroupDocs.Editor for .NET', 'GroupDocs.Editor for .NET is a developer API to integrate with popular HTML Open-Source and 3rd party editors to manipulate, convert and edit. NET. This Editor API can load documents, convert them to HTML, push the converted HTML to an external HTML Editor, and saves the HTML to its original file format following any manipulation. They can also fetch resources attached to any document. Supported formats include Microsoft Word, Excel, OpenDocument, Text, Web, and a lot more. GroupDocs.Editor for .NET supports following file formats Microsoft Office Formats Microsoft Word: DOC, DOCX, DOCM, DOT, DOTM, DOTX, FlatOPC, WordML, RTF Microsoft Excel: XLS, XLSX, XLSM, XLT, XLTX, XLTM, XLSB, XLAM, CSV, TSV, SXC, SpreadsheetML, DIF, DSV Microsoft PowerPoint: PPT, PPTX, PPTM, PPS, PPSX, PPSM, POT, POTX, POTM OpenDocument & Other Formats OpenDocument Formats: ODT, OTT, ODS, FODS,…', ARRAY['.NET']::text[], ARRAY['GroupDocs','Editing','.NET']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/GroupDocs.Editor_for_NET.png","mainImage":"assets/catalog/icons/GroupDocs.Editor_for_NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/groupdocs/groupdocs-editor-for--net"}'::jsonb, '{"metaTitle":"GroupDocs.Editor for .NET | Greatstone","metaDescription":"GroupDocs.Editor for .NET","socialImage":""}'::jsonb, now());
