INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('4f534def-a955-4d44-8870-6b42aa489d3c', '11111111-1111-4111-8111-111111111111', 'product', 'f87702fd-418c-4b91-a827-997c410da59e', '14bd0e56-daf2-48e0-aa0e-7c79be24e1e1', 'groupdocs-merger-for--net', 'GroupDocs.Merger for .NET', 'GroupDocs.Merger for .NET', 'GroupDocs.Merger for .NET helps developers quickly develop market-leading business applications in .NET. With a couple of code lines, application developers can trim, remove, combine, split, rearrange, swap, single page or a collection of images, pages, slides or diagrams. Securely perform operations on files by removing or setting password protection. Using GroupDocs.Merger for .NET developers can merge; split and perform other related operations on single and batch documents. Dynamically stitch files including Microsoft Word, Excel, PowerPoint, Visio, OpenDocument, PDF, XPS, TXT, CSV, eBook and image formats. GroupDocs.Merger for .NET supports merging the following document file formats: Microsoft Office Formats Word: DOC, DOCM, DOCX, DOT, DOTX, DOTM, RTF Excel: XLS, XLSX, XLSM, XLSB, XLT, XLTM, XLTX, XLAM PowerPoint: PPT, PPTX, PPS, PPSX Visio: VSDX, VSDM, VSSX,…', ARRAY['.NET']::text[], ARRAY['GroupDocs','Merge & Split','.NET']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/GroupDocs.Merger_for_NET.png","mainImage":"assets/catalog/icons/GroupDocs.Merger_for_NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/groupdocs/groupdocs-merger-for--net"}'::jsonb, '{"metaTitle":"GroupDocs.Merger for .NET | Greatstone","metaDescription":"GroupDocs.Merger for .NET","socialImage":""}'::jsonb, now());
