INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('f15ed3ce-b617-48ee-8187-ee1cb5361563', '11111111-1111-4111-8111-111111111111', 'product', 'f87702fd-418c-4b91-a827-997c410da59e', '0166bee2-c6f8-4d0a-88c9-c4b9e2233685', 'groupdocs-metadata-for-java', 'GroupDocs.Metadata for Java', 'GroupDocs.Metadata for Java', 'GroupDocs.Metadata for Java API is a versatile Java-based application that helps developers control metadata from an array of images, documents and media file formats without requiring and 3rd party software installation. This robust metadata automation library provides the toolset to swiftly insert metadata extractor, comparison viewer, editor, remover and exporter features in documents for example PDFs, PowerPoint presentations, Microsoft Office Word, Excel spreadsheets, Outlook emails, Photoshop, audio, video, Project, Visio diagrams, OneNote, images, AutoCAD, metafiles and a lot more. The Metadata API is user friendly and intuitive. It reads the input file to analyse the metadata information and processed document metadata. Metadata standards including native XMP, EXIF, IPTC, Image Resource Blocks, ID3 and custom metadata properties are integrated in the API.…', ARRAY['Java']::text[], ARRAY['GroupDocs','Metadata','Java']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/GroupDocs.MetaData_for_Java.png","mainImage":"assets/catalog/icons/GroupDocs.MetaData_for_Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/groupdocs/groupdocs-metadata-for-java"}'::jsonb, '{"metaTitle":"GroupDocs.Metadata for Java | Greatstone","metaDescription":"GroupDocs.Metadata for Java","socialImage":""}'::jsonb, now());
