INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('15dd1b2f-1ee8-4c1d-88cf-b7426891a0e9', '11111111-1111-4111-8111-111111111111', 'product', 'f87702fd-418c-4b91-a827-997c410da59e', 'b7de9d2b-901b-41ab-8c93-eba23b3597b1', 'groupdocs-parser-for--net', 'GroupDocs.Parser for .NET', 'GroupDocs.Parser for .NET', 'GroupDocs.Parser for .NET is a developer API for .NET to extract raw or formatted text, metadata and images from documents, spreadsheets, presentations, emails & archives. Developers can extract raw, formatted & structured text and metadata from files. Using GroupDocs.Parser for .NET, developers, are able to perform parsing of secure and encrypted documents in formats including Word, Excel, PowerPoints, OneNote, PDF and ZIP archives. GroupDocs.Parser for .NET supports following document file formats: Text Extraction Text: DOC, DOCX, DOT, DOTM, DOTX, DOCM, RTF, ODT, OTT, TXT, MD, WordprocessingML (XML) Spreadsheets: XLS, XLSX, CSV, XLSM, XLSB, ODS, SpreadsheetML (XML), XLT, XLTX, XLTM, OTS, XLA,, XLAM, TSV Presentations: PPT, PPTX, PPTM, PPS, PPSX, PPSM, POT, POTX, POTM, ODP, OTP OneNote: ONE Email: MSG, EML, EMLX, PST, OST, MS EXCHANGE SERVER, POP, IMAP Electronic…', ARRAY['.NET']::text[], ARRAY['GroupDocs','Parsing & Extraction','.NET']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/GroupDocs.Parser_for_NET.png","mainImage":"assets/catalog/icons/GroupDocs.Parser_for_NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/groupdocs/groupdocs-parser-for--net"}'::jsonb, '{"metaTitle":"GroupDocs.Parser for .NET | Greatstone","metaDescription":"GroupDocs.Parser for .NET","socialImage":""}'::jsonb, now());
