INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('67e717be-d6de-4be0-b2d2-707941d920f0', '11111111-1111-4111-8111-111111111111', 'product', 'f87702fd-418c-4b91-a827-997c410da59e', 'db0d283f-c559-46fc-8371-3dd33da9b62e', 'groupdocs-search-for--net', 'GroupDocs.Search for .NET', 'GroupDocs.Search for .NET', 'The GroupDocs.Search for .NET API is an enterprise reading developer library for .NET platforms. This .NET library supports simple to sophisticated search features including merging and collecting multiple indexes, using Regular Expression (regex), Simple, Boolean, Fuzzy and other query types to grab your required data and search through indexes, through smart search from files, documents and emails. GroupDocs.Search for .NET is all developers need to developer quick robust, intelligent and versatile search applications. GroupDocs.Search for .NET supports the following formats: Microsoft Office Formats Excel: XLS, XLSX, XLSM, XLT, XLTX,LAM, CSV, TSV, XLTM, XLSB, XLA, PowerPoint: POT, POTX, PPS, PPSX, PPPT, PPTX, PTM, PPSM, POTM Word: DOC, DOCX, DOCM, DOT, DOTX, DOTM Diagram: VSD, VSS Microsoft Compiled HTML: CHM Project: MPP OneNote: ONE OpenDocument & Other Formats…', ARRAY['.NET']::text[], ARRAY['GroupDocs','Search','.NET']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/GroupDocs.Search_for_NET.png","mainImage":"assets/catalog/icons/GroupDocs.Search_for_NET.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/groupdocs/groupdocs-search-for--net"}'::jsonb, '{"metaTitle":"GroupDocs.Search for .NET | Greatstone","metaDescription":"GroupDocs.Search for .NET","socialImage":""}'::jsonb, now());
