INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('903f00f3-33aa-460e-b41e-d6bb5a34ade2', '11111111-1111-4111-8111-111111111111', 'product', 'f87702fd-418c-4b91-a827-997c410da59e', '150eeeb2-feac-4f10-b995-f113b4a14a56', 'groupdocs-viewer-for-java', 'GroupDocs.Viewer for Java', 'GroupDocs.Viewer for Java', 'The GroupDocs.Viewer for Java API helps developers build robust applications in Java and other Java platforms, which renders and displays documents and images of 150+ file formats without requiring any 3rd party software. This viewer API rasterises documents and converts them into SVG+HTML+CSS. The overall document rendering experience is optimised for viewing business documents, email attachments, images, text files, diagrams, graphics and PDF files high-fidelity. Developers have the option to add document viewing and reading capabilities in their applications to display whole or partial documents, individual document layer, specific page/cell range, annotations and comments. The rendered documents output is cached to the local disk. Any external cache storage is supported by applying relevant interfaces, such as Amazon S3, Dropbox, Google Drive, Windows Azure,…', ARRAY['Java']::text[], ARRAY['GroupDocs','Viewing','Java']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/GroupDocs.Viewer_for_Java.png","mainImage":"assets/catalog/icons/GroupDocs.Viewer_for_Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/groupdocs/groupdocs-viewer-for-java"}'::jsonb, '{"metaTitle":"GroupDocs.Viewer for Java | Greatstone","metaDescription":"GroupDocs.Viewer for Java","socialImage":""}'::jsonb, now());
