INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('ca16381f-3b1b-4682-aeb3-18c254cd8851', '11111111-1111-4111-8111-111111111111', 'product', 'f87702fd-418c-4b91-a827-997c410da59e', 'f9080f4e-4552-4b5c-a49b-b0a48948b3ba', 'groupdocs-watermark-for-java', 'GroupDocs.Watermark for Java', 'GroupDocs.Watermark for Java', 'Use GroupDocs.Watermark for Java to build Java applications to add, edit, search and remove watermarks in files. With GroupDocs.Watermark for Java developers are able can dynamically apply digital watermarks to many file types and prevent the use of sensitive intellectual property and securely label documents by using native security features of this robust API. Supported document formats and watermark type for each format is listed below: Microsoft Office and Visio Formats Word: DOC, DOCX, DOT, DOTX, DOCM, DOTM, RTF Excel: XLS, XLSX, XLT, XLTX, XLSM, XLTM PowerPoint: PPT, PPTX, PPS, PPSX, POTX, PPTM, PPSM, POTM Visio: VSDX, VSTX, VSSX, VSDM, VSSM, VSTM, VDX, VSX, VTX Adding Watermark PDF: XObject, Artifact, Annotation Word: Shape Excel: Shape, Header & Footer PowerPoint: Shape Visio: Shape Raster Image: Text, Image Multi-page Tiff: Text, Image Animated Gif: Text,…', ARRAY['Java']::text[], ARRAY['GroupDocs','Watermarking','Java']::text[], 'published', false, 'license', 87000, 'GBP', '{"icon":"assets/catalog/icons/GroupDocs.Watermark_for_Java.png","mainImage":"assets/catalog/icons/GroupDocs.Watermark_for_Java.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/groupdocs/groupdocs-watermark-for-java"}'::jsonb, '{"metaTitle":"GroupDocs.Watermark for Java | Greatstone","metaDescription":"GroupDocs.Watermark for Java","socialImage":""}'::jsonb, now());
