INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('12cabcae-fbfe-4330-b5dc-10ca61e14ad2', '11111111-1111-4111-8111-111111111111', 'product', '47a02d77-f197-48e7-8f52-a93c44b6c4cf', '2cea44d6-1162-4e79-b4fc-c844f8b4ed1b', 'able2extract-professional', 'Able2Extract Professional 20', 'Able2Extract Professional – the leading perpetual PDF converter & editor. Convert, edit & automate PDFs with a one-time purchase from Greatstone.', 'At Greatstone International, we are proud to be an authorised reseller of Able2Extract Professional the most powerful, feature-rich, and cost-effective perpetual desktop PDF solution trusted by enterprises, professionals, and government organisations worldwide. Unlike subscription-only alternatives, Able2Extract Professional gives you lifetime usage rights with a one-time purchase, making it the go-to choice for businesses seeking long-term stability and value. Why Choose Able2Extract Professional? Perpetual Licence No Ongoing Fees Own your software outright. Pay once, use forever, without being tied to recurring subscriptions. Industry-Leading PDF Conversion Convert PDFs to fully editable formats such as Microsoft Word, Excel, PowerPoint, AutoCAD, HTML, and more with unmatched accuracy. Seamless PDF Editing Make quick changes to text, images, and pages directly…', '{}', ARRAY['Investintech','OCR & Recognition']::text[], 'published', true, 'license', 8000, 'GBP', '{"icon":"assets/catalog/icons/able2extract-logo_1759067929.png","mainImage":"assets/catalog/icons/able2extract-logo_1759067929.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/investintech/able2extract-professional"}'::jsonb, '{"metaTitle":"Able2Extract Professional – Perpetual Desktop PDF Converter","metaDescription":"Able2Extract Professional – the leading perpetual PDF converter & editor. Convert, edit & automate PDFs with a one-time purchase from Greatstone.","socialImage":""}'::jsonb, now());
