INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('65095d05-50e4-40c3-9a9e-f36bb9c4354f', '11111111-1111-4111-8111-111111111111', 'product', '61076929-035c-4c7c-9ec9-d1c2cd669f8c', '2cea44d6-1162-4e79-b4fc-c844f8b4ed1b', 'iriscan-desk-5', 'IRIScan Desk 5', 'A versatile USB-powered document camera that enables contact-free scanning of your books, contracts, passports, drawings, deeds, and more.', 'Scan books at top speed without constraints (max. A3) With IRIScan Desk, you can scan your books at an impressive speed. In just three seconds, you can scan and export a double page to black and white PDF. The smart image flattening and edge correction algorithm ensures you get a perfect result every time. This document camera detects page changes automatically and erases all traces of your fingers, giving you a clean and professional output. You can also set a programmable timer to perform scans at regular intervals. Additionally, IRIScan Desk merges your book pages by marking the front and back covers, making it easy to export them to ePub, PDF, or even better, combined with Readiris Corporate (optional), to .MP3 and .WAV audio files. This means you can read your books on any reader, tablet or smartphone. IRIScan Desk is an unrivalled book scanner that guarantees…', '{}', ARRAY['I.R.I.S.','OCR & Recognition']::text[], 'published', false, 'license', 13400, 'GBP', '{"icon":"assets/catalog/icons/iriscan-desk-pro-illustration-1_1687436093.png","mainImage":"assets/catalog/icons/iriscan-desk-pro-illustration-1_1687436093.png","gallery":["https://www.greatstonesoftware.co.uk/storage/gallery/fullres/iriscan-desk5pro-dsc4599_1687436848.jpg","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/iriscan-desk5pro-dsc4599_1687436848.jpg","https://www.greatstonesoftware.co.uk/storage/gallery/fullres/iriscan-desk-5pro-dsc3384_1687436859.jpg","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/iriscan-desk-5pro-dsc3384_1687436859.jpg","https://www.greatstonesoftware.co.uk/storage/gallery/fullres/iriscan-desk5pro-packshot-1_1687436914.jpg","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/iriscan-desk5pro-packshot-1_1687436914.jpg","https://www.greatstonesoftware.co.uk/storage/gallery/fullres/iriscan-desk5pro-dsc4772_1687437009.jpg","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/iriscan-desk5pro-dsc4772_1687437009.jpg"],"sourceUrl":"https://www.greatstonesoftware.co.uk/iris/iriscan-desk-5"}'::jsonb, '{"metaTitle":"IRIScan Desk 5 | IRIS | Greatstone","metaDescription":"A versatile USB-powered document camera that enables contact-free scanning of your books, contracts, passports, drawings, deeds, and more.","socialImage":""}'::jsonb, now());
