INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('ab7c84b8-e500-4e7a-b09b-9b29d0fb0db9', '11111111-1111-4111-8111-111111111111', 'product', '61076929-035c-4c7c-9ec9-d1c2cd669f8c', '2cea44d6-1162-4e79-b4fc-c844f8b4ed1b', 'iriscan-desk-6', 'IRIScan Desk 6', 'A versatile, cutting-edge, professional, AI-enabled document scanner with support for distance learning sessions.', 'The IRIScan Desk 6 is the only option you need for efficient scanning of your documents and pocketbooks. With its advanced functionality, this scanner simplifies the scanning process and produces highly searchable content. Its distinctive design and seamless integration of technologies make it easy to manage and access word documents. Feed your document into the device and let it do the work - the IRIScan Desk 6 is the most cost-effective solution for all your scanning needs. Whether you''re at home, in the office, or traveling, the IRIScan Desk 6 document scanner is a perfect fit. With its exclusive and truly portable USB-powered design, you can easily archive books, loose papers, and even your favorite print magazines. This scanner provides a user-friendly and efficient way to scan both texts and pictures without the need for complicated directory structures. The…', '{}', ARRAY['I.R.I.S.','OCR & Recognition']::text[], 'published', false, 'license', 16700, 'GBP', '{"icon":"assets/catalog/icons/iriscan-desk-6-business-with-a-book-on-scan-pad_1687463855.png","mainImage":"assets/catalog/icons/iriscan-desk-6-business-with-a-book-on-scan-pad_1687463855.png","gallery":["https://www.greatstonesoftware.co.uk/storage/gallery/fullres/a-man-open-a-book-from-top-view_1687462552.jpg","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/a-man-open-a-book-from-top-view_1687462552.jpg","https://www.greatstonesoftware.co.uk/storage/gallery/fullres/a-lady-displaying-her-artwork-via-video-confirming-from-home_1687462583.jpg","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/a-lady-displaying-her-artwork-via-video-confirming-from-home_1687462583.jpg","https://www.greatstonesoftware.co.uk/storage/gallery/fullres/isd6pro-book-situation-face-small_1687462609.jpg","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/isd6pro-book-situation-face-small_1687462609.jpg","https://www.greatstonesoftware.co.uk/storage/gallery/fullres/iriscan-desk-5pro-dsc3384_1687462661.jpg","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/iriscan-desk-5pro-dsc3384_1687462661.jpg"],"sourceUrl":"https://www.greatstonesoftware.co.uk/iris/iriscan-desk-6"}'::jsonb, '{"metaTitle":"IRIScan Desk 6 | IRIS | Greatstone","metaDescription":"A versatile, cutting-edge, professional, AI-enabled document scanner with support for distance learning sessions.","socialImage":""}'::jsonb, now());
