INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('1a46e6b6-7b73-42f8-9380-13b772096ba2', '11111111-1111-4111-8111-111111111111', 'product', '61076929-035c-4c7c-9ec9-d1c2cd669f8c', '2cea44d6-1162-4e79-b4fc-c844f8b4ed1b', 'readiris-pdf-23-for-mac', 'Readiris PDF for Mac', 'Readiris PDF for Mac is a feature-rich and easy-to-use PDF management application, that offers advanced OCR features in a single platform.', 'Ensure your business operates at its full potential by making use of the All-in-one PDF creator and converter Readiris PDF for Mac from IRIS, a Canon company and the world leader in OCR, PDF and Portable Scanners. Specifically designed to cater to paperless offices, the Readiris PDF for Mac edition 2023 offers a comprehensive set of tools for easily managing and converting PDFs, images, and scans. With this powerful PDF management and conversion tool, you can streamline your workflow and get more done in less time. If you find yourself struggling to manage PDF files, Readiris PDF is the solution you need. With a variety of useful features, this software allows for a seamless experience. You can easily and securely convert different formats to PDF, as well as edit, annotate, split, sort, amend, compress, e-sign, and share your documents with ease. If you frequently…', ARRAY['macOS']::text[], ARRAY['I.R.I.S.','OCR & Recognition','macOS']::text[], 'published', false, 'license', 6300, 'GBP', '{"icon":"assets/catalog/icons/ripdf-logo-icon-2350_1686654178.png","mainImage":"assets/catalog/icons/ripdf-logo-icon-2350_1686654178.png","gallery":["https://www.greatstonesoftware.co.uk/storage/gallery/cropped/youtube1_1687362531.png"],"sourceUrl":"https://www.greatstonesoftware.co.uk/iris/readiris-pdf-23-for-mac"}'::jsonb, '{"metaTitle":"Readiris PDF 23 for Mac | IRIS | Greatstone","metaDescription":"Readiris PDF for Mac is a feature-rich and easy-to-use PDF management application, that offers advanced OCR features in a single platform.","socialImage":""}'::jsonb, now());
