INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('bbd29c2a-c503-4ab6-ba94-17962ea33871', '11111111-1111-4111-8111-111111111111', 'product', 'b4555dc2-4bb0-45ca-92e2-60488dd52c49', '845d2bd2-3194-47b4-a075-bfd0ae454a40', 'iron-print-for-net', 'Iron Print for .NET', 'Iron Print for .NET', 'IronPrint is a comprehensive print library for .NET created by Iron Software. This library is compatible with various operating systems, such as Windows, macOS, Android, and iOS. You can use the library to print documents in different formats such as PDF, PNG, HTML , TIFF, GIF, JPEG, IMAGE, and BITMAP. Additionally, you can customize your print settings and display a print dialog before printing. You can also explore the library''s features for free in C#. IronPrint is a comprehensive print library for .NET, developed by Iron Software. The library is designed to work seamlessly with a wide range of environments, including Windows, macOS, Android, and iOS. With IronPrint, you can easily print documents in various formats, such as PDF, PNG, HTML, TIFF, GIF, JPEG, IMAGE, and BITMAP. Additionally, you have the flexibility to customize print settings according to your…', ARRAY['.NET']::text[], ARRAY['Iron Software','Printing','.NET']::text[], 'published', false, 'license', 50900, 'GBP', '{"icon":"assets/catalog/icons/ironprint_1708944119.png","mainImage":"assets/catalog/icons/ironprint_1708944119.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/ironsoftware/iron-print-for-net"}'::jsonb, '{"metaTitle":"Iron Print for .NET | Greatstone","metaDescription":"Iron Print for .NET","socialImage":""}'::jsonb, now());
