INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('4b3ed8ee-c170-4a0c-baf5-3215d051bc0e', '11111111-1111-4111-8111-111111111111', 'product', 'b4555dc2-4bb0-45ca-92e2-60488dd52c49', '42323758-6c49-488f-80bf-86caec7c6d8c', 'iron-qr-for-net', 'Iron QR for .NET', 'Iron QR for .NET', 'IronQR is a C# library that is capable of generating and reading QR codes. The library comes with advanced machine-learning features and is suitable for use on mobile, desktop, and cloud platforms. It is highly customizable, allowing users to generate QR codes on a variety of platforms, including iOS, Android, and Xamarin. In addition, it includes a QR code reader for mobile devices, and its machine learning model ensures accurate detection and reading of QR codes.', ARRAY['.NET']::text[], ARRAY['Iron Software','Barcode & QR','.NET']::text[], 'published', false, 'license', 10200, 'GBP', '{"icon":"assets/catalog/icons/ironqr_1708944967.png","mainImage":"assets/catalog/icons/ironqr_1708944967.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/ironsoftware/iron-qr-for-net"}'::jsonb, '{"metaTitle":"Iron QR for .NET | Greatstone","metaDescription":"Iron QR for .NET","socialImage":""}'::jsonb, now());
