INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('f48b2a5b-fabf-4ba2-a653-59fc531d90d3', '11111111-1111-4111-8111-111111111111', 'product', 'b4555dc2-4bb0-45ca-92e2-60488dd52c49', '347c33ef-802b-4221-8d97-4b1e532ce158', 'iron-word-for-net', 'Iron Word for .NET', 'Iron Word for .NET', 'IronWord is a library from Iron Software that allows .NET applications to work with Word documents effectively. It offers a wide range of functionalities, such as loading, manipulating, and saving Word and Docx documents. It also provides features for configuring paper size, page orientation, margins, and background colour through PageSetup. With IronWord, you can handle text content, styles, splitting, appending text, and adding images through TextRun. You can manage font family, size, colour, bold, italic, strikethrough, underline, superscript, and subscript through TextStyle. You can add text runs, images, shapes, and set styles, alignments, bullets, and numbering lists through Paragraphs. Additionally, you can manipulate table structure, including adding rows, getting and setting cell values, removing rows, merging cells, and more through Table. You can also load…', ARRAY['.NET']::text[], ARRAY['Iron Software','Word Processing','.NET']::text[], 'published', false, 'license', 50900, 'GBP', '{"icon":"assets/catalog/icons/ironword_1708944895.png","mainImage":"assets/catalog/icons/ironword_1708944895.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/ironsoftware/iron-word-for-net"}'::jsonb, '{"metaTitle":"Iron Word for .NET | Greatstone","metaDescription":"Iron Word for .NET","socialImage":""}'::jsonb, now());
