INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('a8a978ba-5e2d-4800-b016-54eac0b7574c', '11111111-1111-4111-8111-111111111111', 'product', 'b4555dc2-4bb0-45ca-92e2-60488dd52c49', '91301607-b61c-4dd5-8dcd-3f778ae0afe2', 'iron-zip-for-net', 'Iron Zip for .NET', 'Iron Zip for .NET', 'IronZIP is a C# Archive Compression and Decompression Library developed by Iron Software. This library can handle a variety of formats including ZIP, TAR, GZIP, and BZIP2. You can download the library to compress and decompress files. With IronZIP, you can also customize the compression levels from 0 to 9, extract content from compressed archives, append files to existing ZIP archives, and even generate new ZIP files.', ARRAY['.NET']::text[], ARRAY['Iron Software','Archiving & Compression','.NET']::text[], 'published', false, 'license', 50900, 'GBP', '{"icon":"assets/catalog/icons/ironzip_1708944379.png","mainImage":"assets/catalog/icons/ironzip_1708944379.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/ironsoftware/iron-zip-for-net"}'::jsonb, '{"metaTitle":"Iron Zip for .NET | Greatstone","metaDescription":"Iron Zip for .NET","socialImage":""}'::jsonb, now());
