INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('510f2016-60bf-457a-912a-e951748fe30a', '11111111-1111-4111-8111-111111111111', 'product', 'b4555dc2-4bb0-45ca-92e2-60488dd52c49', '42323758-6c49-488f-80bf-86caec7c6d8c', 'ironbarcode', 'IronBarcode for .NET', 'Using the IronBarcode C# library, .NET developers can build solutions to read and write QR and Barcodes with a few lines of code.', 'Generate barcodes & QR codes and read from scanned images. Using this C# library .NET developers can build solutions to read and write QR and barcodes with a few lines of code. Codes can be read from one or multiple pages of PDF documents or multipage TIFFs. This feature-rich library allows developers to style QR and barcodes include resizing barcodes, setting margins, changing background colours, changing barcode colours, verifying that the output barcode is still readable, and exporting HTML from a generated barcode. It can export a barcode as a standalone HTML document with no external assets, as a standalone HTML tag, or as a data URI. For QR codes, having a logo graphic placed and snapped to grid in the exact centre of the image is easy. Logos can be coloured to match a specific brand or graphic identity. Core Features: 2-Dimensional Matrix Barcode Formats…', ARRAY['.NET']::text[], ARRAY['Iron Software','Barcode & QR','.NET']::text[], 'published', false, 'license', 50900, 'GBP', '{"icon":"assets/catalog/icons/ironbarcode_1708946954.png","mainImage":"assets/catalog/icons/ironbarcode_1708946954.png","gallery":["https://www.greatstonesoftware.co.uk/storage/gallery/cropped/how-to-generate-qr-codes-and-barcodes-in-c-for-net-5-using-iron-barcode_1666437072.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/how-to-generate-a-qr-code-using-c-with-ironbarcode_1666437205.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/how-to-read-barcodes-in-c-for-net-5-using-iron-barcode_1666437359.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/how-to-generate-barcode-images-in-c-for-net-using-iron-barcode_1666437500.png"],"sourceUrl":"https://www.greatstonesoftware.co.uk/ironsoftware/ironbarcode"}'::jsonb, '{"metaTitle":"IronBarcode | Barcodes & QR Code Generation | Iron Software","metaDescription":"Using the IronBarcode C# library, .NET developers can build solutions to read and write QR and Barcodes with a few lines of code.","socialImage":""}'::jsonb, now());
