INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('525755bb-d2e4-41d3-a829-8333682f97a3', '11111111-1111-4111-8111-111111111111', 'product', 'b4555dc2-4bb0-45ca-92e2-60488dd52c49', '2cea44d6-1162-4e79-b4fc-c844f8b4ed1b', 'ironocr', 'IronOCR for .NET', 'Read and process text from images, Multi Page and Frame TIFF and GIF, System.Drawing Objects and more to achieve OCR accuracy with IronOCR’s C# OCR library. ', 'Read and process text from images, Multi Page and Frame TIFF and GIF, System.Drawing Objects and PDF documents to achieve 99.8%+ OCR accuracy with IronOCR s C# OCR library. With over 127 language packs, IronOCR s Tesseract 5 OCR engine can output content as structured data, text strings or searchable PDFs. Low quality barcodes are automatically corrected to ensure maximum throughput and efficiency. Core Features: Read OCR from Many Formats Low Quality Input Correction with Advanced Computer Vision Text, Barcode and Specialist Document Reading with Concurrency Simple and Structured Data Output with Analytics', ARRAY['.NET']::text[], ARRAY['Iron Software','OCR & Recognition','.NET']::text[], 'published', false, 'license', 50900, 'GBP', '{"icon":"assets/catalog/icons/ironocr_1708946446.png","mainImage":"assets/catalog/icons/ironocr_1708946446.png","gallery":["https://www.greatstonesoftware.co.uk/storage/gallery/cropped/how-to-extract-text-from-images-in-c_1666434137.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/ironocr-as-an-alternative-to-patagames-tesseractnet_1666434468.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/why-ironocr-is-better-than-the-tesseract-4-nuget-package_1666434592.png"],"sourceUrl":"https://www.greatstonesoftware.co.uk/ironsoftware/ironocr"}'::jsonb, '{"metaTitle":"IronOCR for .NET | C# OCR Library | Iron Software","metaDescription":"Read and process text from images, Multi Page and Frame TIFF and GIF, System.Drawing Objects and more to achieve OCR accuracy with IronOCR’s C# OCR library. ","socialImage":""}'::jsonb, now());
