INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('c3113017-155d-4be9-ab86-9ed50cd44968', '11111111-1111-4111-8111-111111111111', 'product', 'b4555dc2-4bb0-45ca-92e2-60488dd52c49', 'd9850036-dcac-428f-9521-78346e13d26c', 'ironpdf', 'IronPDF for .NET', 'Build, format and manipulate PDFs that have an HTML look and feel with IronPDF. Converting to PDF is simple and lightning-quick with a few lines of code.', 'IronPDF is a reliable solution that simplifies the challenging task of adding PDF generation to your app. It automates the process of converting formatted documents into PDFs, enabling you to achieve the following tasks with .NET: Convert web forms, local HTML pages, and other web pages to PDF Allow users to download, email, or store documents in the cloud Produce a wide range of documents, including invoices, quotes, reports, and contracts Work with various web development frameworks such as ASP.NET, ASP.NET Core, web forms, MVC, Web APIs on .NET Framework, and .NET Core.', ARRAY['.NET']::text[], ARRAY['Iron Software','PDF','.NET']::text[], 'published', true, 'license', 50900, 'GBP', '{"icon":"assets/catalog/icons/ironpdf_1708945913.png","mainImage":"assets/catalog/icons/ironpdf_1708945913.png","gallery":["https://www.greatstonesoftware.co.uk/storage/gallery/cropped/htmltopdf-c_1666191974.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/convert-aspx-to-pdf-in-aspdotnet_1666192477.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/create-a-pdf-report-in-c_1666192832.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/generate-pdf-files-in-net-6_1666193010.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/how-to-create-a-pdf-in-c-using-ironpdf_1666193117.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/comparing-ironpdf-to-itextsharp-in-c_1666193254.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/a-comparison-of-ironpdf-vs-selectpdf_1666193623.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/how-to-convert-an-aspnet-mvc-view-to-pdf-using-ironpdf_1666193740.png"],"sourceUrl":"https://www.greatstonesoftware.co.uk/ironsoftware/ironpdf"}'::jsonb, '{"metaTitle":"IronPDF | PDF Generation & Manipulation | Iron Software","metaDescription":"Build, format and manipulate PDFs that have an HTML look and feel with IronPDF. Converting to PDF is simple and lightning-quick with a few lines of code.","socialImage":""}'::jsonb, now());
