INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('bb46cec7-2fdc-4842-b0fd-cd6254fa319c', '11111111-1111-4111-8111-111111111111', 'product', 'b4555dc2-4bb0-45ca-92e2-60488dd52c49', '91f15861-f991-468b-9a13-385390b6d80b', 'ironsuite', 'IronSuite for .NET', 'Get 5 components for the price of 2 with IronSuite from Iron Software, including C# libraries for PDF, Excel, OCR and more.', 'Iron Suite is a developer suite that includes nine components designed by Iron Software. It is available for the price of two components. The components include tools for PDF generation, MSExcel automation, barcode creation and reading, web scraping, file compression, OCR, and document printing. The components include: IronPDF: A tool to generate, format and manipulate PDFs. IronWord: A tool to create, edit and automate MSExcel cells, workbooks and worksheets without requiring Office Interop objects. IronXL: A tool to create, edit and automate MSExcel cells, workbooks and worksheets without requiring Office Interop objects. IronQR: A tool to create, write and read multiple format barcodes. IronWebscraper: A tool to scrape data dynamically from the web. IronBarcode: A tool to create, write and read multiple format barcodes. IronZIP: A tool to compress and decompress…', ARRAY['.NET']::text[], ARRAY['Iron Software','Suites & Bundles','.NET']::text[], 'published', false, 'license', 101800, 'GBP', '{"icon":"assets/catalog/icons/ironsuite_1708944534.png","mainImage":"assets/catalog/icons/ironsuite_1708944534.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/ironsoftware/ironsuite"}'::jsonb, '{"metaTitle":"IronSuite | Ultimate Developer Suite from Iron Software","metaDescription":"Get 5 components for the price of 2 with IronSuite from Iron Software, including C# libraries for PDF, Excel, OCR and more.","socialImage":""}'::jsonb, now());
