INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('ae269fc1-9fac-4984-a1fa-0229e87f6a40', '11111111-1111-4111-8111-111111111111', 'product', 'b4555dc2-4bb0-45ca-92e2-60488dd52c49', 'b7de9d2b-901b-41ab-8c93-eba23b3597b1', 'ironwebscraper', 'IronWebscraper for .NET', 'IronWebscraper is a C# library that provides developers with the framework to build powerful data web extraction engines in .NET.', 'IronWebScraper is a framework and class library for the .NET programming platform written in C#. It enables developers to extract the content of websites programmatically. This is particularly useful for reverse engineering websites or intranets and converting them into databases or JSON data. It can also be used to download large volumes of documents from the internet. Iron Web Scraper shares many similarities with Scrapy, the Python library for web scraping. However, IronWebScraper leverages the advantages of C#, specifically its ability to debug and step through code while the web scraping process is in progress.', ARRAY['.NET']::text[], ARRAY['Iron Software','Parsing & Extraction','.NET']::text[], 'published', false, 'license', 50900, 'GBP', '{"icon":"assets/catalog/icons/ironwebscraper_1708946656.png","mainImage":"assets/catalog/icons/ironwebscraper_1708946656.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/ironsoftware/ironwebscraper"}'::jsonb, '{"metaTitle":"Iron Webscraper | Web Content Extraction | Iron Software","metaDescription":"IronWebscraper is a C# library that provides developers with the framework to build powerful data web extraction engines in .NET.","socialImage":""}'::jsonb, now());
