INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('b4d108b6-c726-4861-83d9-c195f310aaa4', '11111111-1111-4111-8111-111111111111', 'product', 'b4555dc2-4bb0-45ca-92e2-60488dd52c49', 'dc8fc4d3-68b8-4b41-97d9-76bcf1dd75af', 'ironxl', 'IronXL for .NET', 'With the IronXL C# library, you can process, automate and dynamically manipulate Excel file formats without requiring Office Interop objects.', 'IronXL, a software library from Iron Software, enables you to easily read, create, process, and automate Excel Spreadsheet Files in C# and VB.NET applications. With IronXL, you can work with Excel files in formats such as XLS, XLSX, and CSV in any .NET language. The software library doesn''t require you to install Excel or Interop on your server, and it offers a more efficient and user-friendly API than Microsoft.Office.Interop.Excel. You can use IronXL on various platforms such as .NET Framework 4.6.2 and above for Windows and Azure, .NET Core 2 and above for Windows, Linux, MacOS, and Azure, as well as .NET 5, .NET 6, .NET 7, Mono, Mobile, and Xamarin. IronXL, a software library from Iron Software, enables you to process and automate Excel Spreadsheet Files in C# & VB.NET Applications. With IronXL, reading and creating Excel files (including XLS, XLSX and CSV…', ARRAY['.NET']::text[], ARRAY['Iron Software','Spreadsheets','.NET']::text[], 'published', false, 'license', 50900, 'GBP', '{"icon":"assets/catalog/icons/ironxl_1708945071.png","mainImage":"assets/catalog/icons/ironxl_1708945071.png","gallery":["https://www.greatstonesoftware.co.uk/storage/gallery/cropped/create-an-excel-file-in-c_1666282101.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/how-to-read-excel-files-in-c-ironxl-for-net-no-interop-required_1666434936.png","https://www.greatstonesoftware.co.uk/storage/gallery/cropped/how-to-read-csv-files-in-c-using-ironxl_1666435217.png"],"sourceUrl":"https://www.greatstonesoftware.co.uk/ironsoftware/ironxl"}'::jsonb, '{"metaTitle":"IronXL | Microsoft Excel Automation | Iron Software","metaDescription":"With the IronXL C# library, you can process, automate and dynamically manipulate Excel file formats without requiring Office Interop objects.","socialImage":""}'::jsonb, now());
