INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('fd22e3d8-023f-4857-9ecb-dbf1e561664f', '11111111-1111-4111-8111-111111111111', 'product', 'a2809936-6ea4-47f2-9482-a0da4762e2a2', 'd9850036-dcac-428f-9521-78346e13d26c', 'pdflib', 'PDFlib – Enterprise PDF Generation Toolkit', 'PDFlib is the premier toolkit for application developers looking to implement PDF generation & manipulation features in their enterprise. ', 'PDFlib is engineered for professional document creation, automation and high-volume output. It allows developers to programmatically create PDF files from scratch or dynamically convert existing data, content and layouts into beautiful, print-ready documents. Unlike simple PDF wrapper libraries, PDFlib offers both low-level and high-level APIs, giving you full control over layout, typesetting, graphics, accessibility, and document structure. Low-Level PDF Creation Precision Page Composition PDFlib s low-level API lets you place every element text, images, graphics, shapes exactly where you want it on the page. Ideal when your application already controls the layout (e.g., custom rendering engines, dashboards, or templates). High-Level PDF Formatting Automated Professional Layout For more complex documents, PDFlib s high-level toolset handles the heavy lifting:…', '{}', ARRAY['PDFlib','PDF']::text[], 'published', true, 'license', 65000, 'GBP', '{"icon":"assets/catalog/icons/PDFlib-9.2.0.png","mainImage":"assets/catalog/icons/PDFlib-9.2.0.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/pdflib/pdflib"}'::jsonb, '{"metaTitle":"PDFlib | PDF Generation Toolkit | Greatstone","metaDescription":"PDFlib is the premier toolkit for application developers looking to implement PDF generation & manipulation features in their enterprise. ","socialImage":""}'::jsonb, now());
