INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('adc69467-7a90-475b-8c1b-455694597a29', '11111111-1111-4111-8111-111111111111', 'product', 'a2809936-6ea4-47f2-9482-a0da4762e2a2', 'd9850036-dcac-428f-9521-78346e13d26c', 'pdflib-pdi', 'PDFlib + PDI – PDF Creation & Import Engine', 'Application developers can use PDFlib PDI to process open PDF documents and add Pages, Text, Images, Footers, Barcodes and more into the output document. ', 'PDFlib + PDI is a premium development library that extends PDFlib with full PDF import and processing capabilities. It enables businesses to automate workflows that rely on existing PDF templates, forms, statements, receipts, certificates and other structured documents. Where PDFlib focuses on PDF creation, PDI adds the ability to: Import PDF pages as reusable graphics Assemble multiple documents into a single output Merge dynamic content onto static templates Extract metadata and page information Combine PDF generation and PDF reuse in one unified workflow This makes PDFlib + PDI ideal for enterprise systems that must generate personalised, data-driven, production-ready documents using pre-designed layouts. Perfect Use Cases for PDFlib + PDI PDFlib + PDI shines in high-volume business automation, including: Invoice and billing generation using existing templates…', '{}', ARRAY['PDFlib','PDF']::text[], 'published', false, 'license', 80000, 'GBP', '{"icon":"assets/catalog/icons/PDFlib-PDI-9.2.0.png","mainImage":"assets/catalog/icons/PDFlib-PDI-9.2.0.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/pdflib/pdflib-pdi"}'::jsonb, '{"metaTitle":"PDFlib PDI | PDF Import Library | Greatstone","metaDescription":"Application developers can use PDFlib PDI to process open PDF documents and add Pages, Text, Images, Footers, Barcodes and more into the output document. ","socialImage":""}'::jsonb, now());
