INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('deb639af-bc14-4dc4-89bd-39d26bed04e8', '11111111-1111-4111-8111-111111111111', 'product', 'a2809936-6ea4-47f2-9482-a0da4762e2a2', 'd9850036-dcac-428f-9521-78346e13d26c', 'pdflib-pps', 'PDFlib Personalization Server - Enterprise PDF Personalisation Engine', 'The PDFlib Personalization Server (PPS) comprises PDFlib+PDI and additional functions and features to process variable data with PDFlib Blocks.', 'PDFlib PPS is the enterprise-grade automation engine built on top of PDFlib + PDI. It enables businesses to combine pre-designed PDF templates with dynamic content, creating personalised documents at high speed ideal for large-scale production environments such as banks, insurers, logistics companies, government agencies and digital platforms. With PPS, developers can: Generate thousands (or millions) of documents efficiently Combine existing PDF templates with dynamic text, images, tables and barcodes Create personalised output for each recipient or transaction Automate document assembly without manual intervention Integrate with server applications in Java, .NET, PHP, Python, C/C++ and many other languages PPS is the top-tier PDFlib product, offering maximum flexibility, scalability and performance for mission-critical PDF generation. Perfect Use Cases for PPS PPS…', '{}', ARRAY['PDFlib','PDF']::text[], 'published', false, 'license', 197000, 'GBP', '{"icon":"assets/catalog/icons/PDFlib-PPS-9.png","mainImage":"assets/catalog/icons/PDFlib-PPS-9.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/pdflib/pdflib-pps"}'::jsonb, '{"metaTitle":"PDFlib Personalization Server | Greatstone International","metaDescription":"The PDFlib Personalization Server (PPS) comprises PDFlib+PDI and additional functions and features to process variable data with PDFlib Blocks.","socialImage":""}'::jsonb, now());
