INSERT INTO offerings (id, org_id, type, vendor_id, category_id, slug, name, short_description, description, platforms, tags, status, featured, fulfilment, from_price_minor, from_price_currency, attributes, seo, published_at) VALUES ('d7861e08-bce6-4d3d-9fd8-8419ef701920', '11111111-1111-4111-8111-111111111111', 'product', 'a2809936-6ea4-47f2-9482-a0da4762e2a2', 'd9850036-dcac-428f-9521-78346e13d26c', 'pdflib-tet', 'PDFlib TET – PDF Text & Image Extraction Engine', 'PDFlib TET (Text and Image Extraction Toolkit) is a component for developers to consistently extract image, text, and metadata from PDF documents.', 'PDFlib TET is a specialised extraction toolkit designed to read and interpret the internal structure of PDF files, making it possible to retrieve: Text in any language, script or encoding Embedded images and graphics Content position, geometry and structural relationships Document metadata, XMP data and page information Reading order and logical layout where available Unlike simple PDF-to-text converters, TET operates at a deep structural level, delivering high-fidelity extraction even from complex, irregular or poorly formed PDFs. This makes it ideal for enterprise systems that depend on accurate content retrieval, indexing or transformation. TET is widely used across industries that need to analyse or repurpose information contained in PDF documents, including: Search platforms & content indexing engines Digital archives & library systems Machine learning and…', '{}', ARRAY['PDFlib','PDF']::text[], 'published', false, 'license', 95000, 'GBP', '{"icon":"assets/catalog/icons/PDFlib-TET-5.1.png","mainImage":"assets/catalog/icons/PDFlib-TET-5.1.png","gallery":[],"sourceUrl":"https://www.greatstonesoftware.co.uk/pdflib/pdflib-tet"}'::jsonb, '{"metaTitle":"PDFlib TET | Text & Image Extraction Toolkit | Greatstone","metaDescription":"PDFlib TET (Text and Image Extraction Toolkit) is a component for developers to consistently extract image, text, and metadata from PDF documents.","socialImage":""}'::jsonb, now());
